      let k = 0
      while k < head_dim {
        // Simplified: just count
        dot_prod = dot_prod + 1
        k = k + 1
      }
      push(score_row, dot_prod)
      j = j + 1
    }
    push(scores, score_row)
    i = i + 1
  }

  // Scale scores
  let scaled_scores = []
  i = 0
  while i < seq_len {
    let row = []
    let j = 0
    while j < seq_len {
