}

fn publish_batch(pub: Publisher, topic: string, messages: any) -> i32 {
    let count = 0;
    let i = 0;
    let len = length(messages);

    while i < len {
        let msg = messages[i];
        if publish_message(pub, topic, msg) {
            count = count + 1;
        }
        i = i + 1;
    }

    return count;
}

