fn discovery_find_service(registry: any, name: string) -> any {
    return discovery_find(registry, name);
}

fn discovery_load_balance(services: any, lb: any) -> any {
    return discovery_select_round_robin(services, lb);
}

fn discovery_get_stats(registry: any) -> any {
    return discovery_stats(registry);
}

// ============================================================================
// Section 4: Circuit Breaker API 재내보내기 (15줄)
// ============================================================================

fn breaker_new(breaker_id: string) -> any {
    return breaker_create(breaker_id);
}

fn breaker_execute(breaker: any) -> bool {
    return breaker_can_execute(breaker);
}

fn breaker_success(breaker: any) -> any {
    return breaker_record_success(breaker);
}

fn breaker_failure(breaker: any) -> any {
    return breaker_record_failure(breaker);
}

fn breaker_metrics(breaker: any) -> any {
    return breaker_get_metrics(breaker);
}

// ============================================================================
// Section 5: Message Queue API 재내보내기 (15줄)
// ============================================================================

fn mq_pub_create() -> any {
    return mq_create_publisher();
}

fn mq_pub_send(pub: any, topic: string, msg: any) -> bool {
    return mq_publish(pub, topic, msg);
}

fn mq_sub_create(id: string) -> any {
    return mq_create_subscriber(id);
}

fn mq_sub_listen(sub: any, topic: string) -> bool {
    return mq_subscribe(sub, topic);
}

// ============================================================================
// Section 6: Unified MSA API (20줄)
// ============================================================================

struct MSACluster {
    rpc_server: any,
    discovery_registry: any,
    circuit_breakers: any,
    message_queues: any,
    metrics: any
}

fn create_msa_cluster(port: i32) -> MSACluster {
    let cluster = MSACluster {
        rpc_server: rpc_server_create(port),
        discovery_registry: discovery_registry_create(),
        circuit_breakers: any(),
        message_queues: any(),
        metrics: struct {}
    };
    return cluster;
}

fn start_msa_cluster(cluster: MSACluster) -> MSACluster {
    cluster.rpc_server = rpc_server_start(cluster.rpc_server);
    return cluster;
}

fn register_msa_service(cluster: MSACluster, name: string, host: string, port: i32) -> MSACluster {
    cluster.discovery_registry = discovery_register_service(cluster.discovery_registry, name, host, port);
    return cluster;
}

// ============================================================================
// Section 7: Metrics and Monitoring (10줄)
// ============================================================================

fn get_msa_metrics(cluster: MSACluster) -> any {
    let metrics = struct {
        rpc_stats: rpc_stats(cluster.rpc_server),
        discovery_stats: discovery_get_stats(cluster.discovery_registry),
        circuit_breakers_count: length(cluster.circuit_breakers),
        message_queues_count: length(cluster.message_queues)
    };
    return metrics;
}
