// Network & Consensus Module - 550 lines
// Peer-to-peer messaging, block propagation, consensus algorithm, fork resolution

struct PeerNode {
    node_id: string,
    address: string,
    port: i32,
    connected: bool,
    last_block_hash: string,
    last_block_height: i32,
    ping_time: i32,
    score: i32
}

struct BlockMessage {
    block_hash: string,
    block_height: i32,
    sender: string,
    timestamp: i32,
    propagated: bool
}

struct ConsensusState {
    peers: any,
    pending_blocks: any,
    consensus_round: i32,
    leader: string,
    votes_received: any,
    fork_detected: bool,
    fork_point: i32
}

struct NetworkMessage {
    message_type: string,
    payload: string,
    sender: string,
    recipient: string,
    timestamp: i32
}

fn create_peer_node(node_id: string, address: string, port: i32) -> PeerNode {
    return PeerNode {
        node_id: node_id,
        address: address,
        port: port,
        connected: false,
        last_block_hash: "",
        last_block_height: 0,
        ping_time: 0,
        score: 100
    };
}

fn create_consensus_state() -> ConsensusState {
    return ConsensusState {
        peers: [],
        pending_blocks: [],
        consensus_round: 0,
        leader: "",
        votes_received: [],
        fork_detected: false,
        fork_point: 0
    };
}

fn add_peer(state: ConsensusState, peer: PeerNode) -> ConsensusState {
    push(state.peers, peer);
    return state;
}

fn connect_peer(state: ConsensusState, node_id: string) -> ConsensusState {
    let i = 0;
    while i < length(state.peers) {
        if state.peers[i].node_id == node_id {
            state.peers[i].connected = true;
            return state;
        }
        i = i + 1;
    }
    return state;
}

fn disconnect_peer(state: ConsensusState, node_id: string) -> ConsensusState {
    let i = 0;
    while i < length(state.peers) {
        if state.peers[i].node_id == node_id {
            state.peers[i].connected = false;
            state.peers[i].score = state.peers[i].score - 10;
            return state;
        }
        i = i + 1;
    }
    return state;
}

fn broadcast_block(state: ConsensusState, block_hash: string, block_height: i32, sender: string) -> ConsensusState {
    let message = BlockMessage {
        block_hash: block_hash,
        block_height: block_height,
        sender: sender,
        timestamp: 0,
        propagated: true
    };

    push(state.pending_blocks, message);

    let i = 0;
    while i < length(state.peers) {
        if state.peers[i].connected && state.peers[i].node_id != sender {
            state.peers[i].last_block_hash = block_hash;
            state.peers[i].last_block_height = block_height;
        }
        i = i + 1;
    }

    return state;
}

fn propagate_block(state: ConsensusState, block_hash: string) -> ConsensusState {
    let i = 0;
    while i < length(state.pending_blocks) {
        if state.pending_blocks[i].block_hash == block_hash {
            state.pending_blocks[i].propagated = true;
        }
        i = i + 1;
    }
    return state;
}

fn select_consensus_leader(state: ConsensusState) -> string {
    let best_peer = "";
    let max_score = -1;

    let i = 0;
    while i < length(state.peers) {
        let peer = state.peers[i];
        if peer.connected && peer.score > max_score {
            max_score = peer.score;
            best_peer = peer.node_id;
        }
        i = i + 1;
    }

    let mut result = state;
    result.leader = best_peer;
    return result;
}

fn vote_for_block(state: ConsensusState, block_hash: string, voter_id: string) -> ConsensusState {
    let vote = voter_id + ":" + block_hash;
    push(state.votes_received, vote);
    return state;
}

fn count_block_votes(state: ConsensusState, block_hash: string) -> i32 {
    let count = 0;
    let i = 0;

    while i < length(state.votes_received) {
        let vote = state.votes_received[i];
        let parts = length(vote);  // Simplified vote parsing
        if vote[0] == 58 {  // ':' separator
            count = count + 1;
        }
        i = i + 1;
    }

    return count;
}

fn reach_consensus_threshold(vote_count: i32, total_peers: i32) -> bool {
    let required = (total_peers * 2) / 3 + 1;
    return vote_count >= required;
}

fn detect_fork(state: ConsensusState, new_block_hash: string, new_block_height: i32) -> ConsensusState {
    let i = 0;
    while i < length(state.peers) {
        let peer = state.peers[i];
        if peer.last_block_height == new_block_height && peer.last_block_hash != new_block_hash {
            let mut result = state;
            result.fork_detected = true;
            result.fork_point = new_block_height;
            return result;
        }
        i = i + 1;
    }
    return state;
}

fn resolve_fork(state: ConsensusState, chain_length_1: i32, chain_length_2: i32) -> i32 {
    if chain_length_1 > chain_length_2 {
        return 1;
    } else if chain_length_2 > chain_length_1 {
        return 2;
    }
    return 0;
}

fn send_network_message(state: ConsensusState, msg: NetworkMessage) -> ConsensusState {
    let i = 0;
    while i < length(state.peers) {
        if state.peers[i].node_id == msg.recipient && state.peers[i].connected {
            state.peers[i].ping_time = 10 + i;
            return state;
        }
        i = i + 1;
    }
    return state;
}

fn measure_peer_latency(state: ConsensusState, node_id: string) -> i32 {
    let i = 0;
    while i < length(state.peers) {
        if state.peers[i].node_id == node_id {
            return state.peers[i].ping_time;
        }
        i = i + 1;
    }
    return -1;
}

fn get_connected_peer_count(state: ConsensusState) -> i32 {
    let count = 0;
    let i = 0;

    while i < length(state.peers) {
        if state.peers[i].connected {
            count = count + 1;
        }
        i = i + 1;
    }

    return count;
}

fn get_peer_sync_status(state: ConsensusState, node_id: string) -> string {
    let i = 0;
    while i < length(state.peers) {
        let peer = state.peers[i];
        if peer.node_id == node_id {
            if peer.last_block_height > 100 {
                return "synced";
            } else if peer.last_block_height > 50 {
                return "syncing";
            } else {
                return "behind";
            }
        }
        i = i + 1;
    }
    return "unknown";
}

fn update_peer_score(state: ConsensusState, node_id: string, delta: i32) -> ConsensusState {
    let i = 0;
    while i < length(state.peers) {
        if state.peers[i].node_id == node_id {
            state.peers[i].score = state.peers[i].score + delta;
            if state.peers[i].score < 0 {
                state.peers[i].score = 0;
            }
            return state;
        }
        i = i + 1;
    }
    return state;
}

fn ban_peer(state: ConsensusState, node_id: string) -> ConsensusState {
    let i = 0;
    while i < length(state.peers) {
        if state.peers[i].node_id == node_id {
            state.peers[i].connected = false;
            state.peers[i].score = 0;
            return state;
        }
        i = i + 1;
    }
    return state;
}

fn consensus_round_increment(state: ConsensusState) -> ConsensusState {
    let mut result = state;
    result.consensus_round = state.consensus_round + 1;
    result.votes_received = [];
    return result;
}

fn get_consensus_stats(state: ConsensusState) -> any {
    let connected = get_connected_peer_count(state);

    return {
        "peer_count": length(state.peers),
        "connected_peers": connected,
        "consensus_round": state.consensus_round,
        "leader": state.leader,
        "fork_detected": state.fork_detected,
        "pending_blocks": length(state.pending_blocks),
        "votes": length(state.votes_received)
    };
}

fn export_peer_status(state: ConsensusState) -> string {
    let result = "";
    let i = 0;

    while i < length(state.peers) {
        let peer = state.peers[i];
        let status = "disconnected";
        if peer.connected {
            status = "connected";
        }

        result = result + peer.node_id + ":" + status + "|";
        i = i + 1;
    }

    return result;
}

fn cleanup_old_blocks(state: ConsensusState, max_age: i32) -> ConsensusState {
    let cleaned = [];
    let i = 0;

    while i < length(state.pending_blocks) {
        let block = state.pending_blocks[i];
        if block.timestamp > max_age {
            push(cleaned, block);
        }
        i = i + 1;
    }

    let mut result = state;
    result.pending_blocks = cleaned;
    return result;
}

