// Complete Information Extraction Pipeline
fn grie_extract_information(text: string) -> any {
    // Step 1: Create entity recognizer
    let ner_model = create_ner_model();
    let entities = perform_ner(text, ner_model);

    // Step 2: Extract relations
    let rel_model = create_relation_prediction_model();
    let relations = predict_relations(entities, text, rel_model);

    // Step 3: Build graph
    let graph = build_graph(entities, relations);

    // Step 4: Create knowledge graph store
    let kg_store = create_knowledge_graph_store();

    // Step 5: Add triples
    let i = 0;
    while i < length(relations) {
        let rel = relations[i];
        let triple = Triple {
            subject: rel.source_id,
            predicate: rel.relation_type,
            object: rel.target_id,
            confidence: rel.confidence,
            timestamp: 0.0,
            source: "extraction"
        };
        add_triple(kg_store, triple);
        i = i + 1;
    }

    // Step 6: Deduplication
    let detector = create_deduplication_detector();
    let dup_count = detect_and_remove_duplicates(kg_store, detector);

    // Step 7: Create result
    let result = {};
    result["entities"] = entities;
    result["relations"] = relations;
    result["graph"] = graph;
    result["kg_store"] = kg_store;
    result["duplicates_removed"] = dup_count;
    result["dedup_efficiency"] = detector.dedup_efficiency;

    return result;
}

// Query the Knowledge Graph
fn grie_query_kg(kg_store: any, subject: string, predicate: string, object: string) -> array {
    let query = KGQuery {
        subject_pattern: subject,
        predicate_pattern: predicate,
        object_pattern: object,
        confidence_threshold: 0.5
    };

    return query_triples(kg_store, query);
}

