fn grie_train_agent(training_texts: array, num_episodes: i32) -> any {
    // Create RL agent
    let rl_agent = create_rl_agent();

    // Create KG store
    let kg_store = create_knowledge_graph_store();

    // Create GRIE agent
    let grie_agent = create_grie_agent(rl_agent, kg_store);

    // Run training loop
    let episode_results = run_learning_loop(grie_agent, training_texts, num_episodes);

    // Create training result
    let result = {};
    result["agent"] = grie_agent;
    result["episodes"] = episode_results;
    result["total_episodes"] = num_episodes;
    result["final_improvement_rate"] = grie_agent.improvement_rate;

    return result;
}

