let last = fruits.pop();  // Some("orange")
fruits.remove(0);  // "apple" 제거

// 접근
println(fruits[0]);
println(fruits.get(0));  // Option<&T> (안전)

// 길이 & 용량
println(fruits.len());       // 원소 개수
println(fruits.capacity());  // 할당된 공간

// 반복
for fruit in &fruits {
    println(fruit);
}

// 수정하면서 반복
for fruit in &mut fruits {
    *fruit = fruit.to_uppercase();
}
