```freelang
fn word_frequency(text: &str) -> Dict<string, i32> {
    let mut freq = Dict::new();
    let words = text.split_whitespace();

    for word in words {
        let count = freq.get(word).unwrap_or(0);
        freq.insert(word.to_string(), count + 1);
    }

    freq
}

