fn assert_true(condition: bool, test_id: string, name: string,
                rule: string, expected: string, actual: string) -> TestResult {
    return TestResult {
        test_id: test_id,
        test_name: name,
        passed: condition,
        rule: rule,
        expected: expected,
        actual: actual,
        metric_value: 0.0,
        metric_unit: "",
        duration_ms: 0.0
    }
}

fn assert_less_than(value: f32, threshold: f32, test_id: string,
                     name: string, rule: string, unit: string) -> TestResult {
    return TestResult {
        test_id: test_id,
        test_name: name,
        passed: value < threshold,
        rule: rule,
        expected: "< " + to_string(threshold) + " " + unit,
        actual: to_string(value) + " " + unit,
        metric_value: value,
        metric_unit: unit,
        duration_ms: 0.0
    }
}

fn assert_greater_than(value: f32, threshold: f32, test_id: string,
                        name: string, rule: string, unit: string) -> TestResult {
    return TestResult {
        test_id: test_id,
        test_name: name,
        passed: value > threshold,
        rule: rule,
        expected: "> " + to_string(threshold) + " " + unit,
        actual: to_string(value) + " " + unit,
        metric_value: value,
        metric_unit: unit,
        duration_ms: 0.0
    }
}

fn assert_geq(value: f32, threshold: f32, test_id: string,
               name: string, rule: string, unit: string) -> TestResult {
    return TestResult {
        test_id: test_id,
        test_name: name,
        passed: value >= threshold,
        rule: rule,
        expected: ">= " + to_string(threshold) + " " + unit,
        actual: to_string(value) + " " + unit,
        metric_value: value,
        metric_unit: unit,
        duration_ms: 0.0
    }
}

