// FreeLang-LLC Phase 5: SIMD Vectorizer
// Purpose: Detect and vectorize loops using SIMD instructions
// Target: AVX2 (256-bit), AVX-512 (512-bit), SSE4.2 (128-bit)
// R1: Vectorization detection >90%, R2: 2-8x speedup
// ~800 lines

// ============================================================================
// Part 1: SIMD Data Types (100 lines)
// ============================================================================

pub enum SimdWidth {
    Sse128,     // 128-bit: 4×f32, 2×f64, 16×i8
    Avx256,     // 256-bit: 8×f32, 4×f64, 32×i8
    Avx512,     // 512-bit: 16×f32, 8×f64, 64×i8
}

pub enum SimdElementType {
    I8,
    I16,
    I32,
    I64,
    F32,
    F64,
}

pub struct SimdVector {
    pub elements: Vec<f64>,
    pub width: SimdWidth,
    pub element_type: SimdElementType,
    pub lane_count: u32,       // number of parallel lanes
    pub alignment: u32,        // memory alignment (16, 32, 64 bytes)
}

impl SimdVector {
    pub fn new_avx256_f32() -> Self {
        Self {
            elements: vec![0.0; 8],
            width: SimdWidth::Avx256,
            element_type: SimdElementType::F32,
            lane_count: 8,
            alignment: 32,
        }
    }

    pub fn new_avx512_f32() -> Self {
        Self {
            elements: vec![0.0; 16],
            width: SimdWidth::Avx512,
            element_type: SimdElementType::F32,
            lane_count: 16,
            alignment: 64,
        }
    }

    pub fn new_sse128_f64() -> Self {
        Self {
            elements: vec![0.0; 2],
            width: SimdWidth::Sse128,
            element_type: SimdElementType::F64,
            lane_count: 2,
            alignment: 16,
        }
    }

    pub fn load(&mut self, data: &[f64]) -> bool {
        if data.len() < self.lane_count as usize {
            return false;
        }
        for i in 0..self.lane_count as usize {
            self.elements[i] = data[i];
        }
        true
    }

    pub fn store(&self, out: &mut Vec<f64>) {
        for &e in &self.elements {
            out.push(e);
        }
    }

    pub fn lane_bytes(&self) -> u32 {
        match self.element_type {
            SimdElementType::I8 => 1,
            SimdElementType::I16 => 2,
            SimdElementType::I32 | SimdElementType::F32 => 4,
            SimdElementType::I64 | SimdElementType::F64 => 8,
        }
    }
}

// ============================================================================
// Part 2: Loop Analysis (150 lines)
// ============================================================================

pub enum LoopDependency {
    Independent,            // No loop-carried dependency — safe to vectorize
    ReadAfterWrite(u32),    // RAW at distance N
    WriteAfterRead(u32),    // WAR at distance N
    WriteAfterWrite,        // WAW — always unsafe
    Indirect,               // Indirect addressing — unknown at compile time
}

pub struct LoopInfo {
    pub id: u32,
    pub trip_count: Option<u32>,       // None = dynamic
    pub step: i32,                      // +1, +2, etc.
    pub access_pattern: String,         // "sequential", "strided", "random"
    pub dependency: LoopDependency,
    pub body_instruction_count: u32,
    pub reduction_variable: Option<String>,  // sum, product, min, max
    pub has_function_call: bool,
    pub inner_loops: u32,
}

impl LoopInfo {
    pub fn new(id: u32) -> Self {
        Self {
            id,
            trip_count: None,
            step: 1,
            access_pattern: "sequential".to_string(),
            dependency: LoopDependency::Independent,
            body_instruction_count: 0,
            reduction_variable: None,
            has_function_call: false,
            inner_loops: 0,
        }
    }

    pub fn is_vectorizable(&self) -> bool {
        // Check all preconditions
        match self.dependency {
            LoopDependency::Independent => {}
            LoopDependency::ReadAfterWrite(d) if d >= 8 => {}  // Safe if distance >= vector width
            _ => return false,
        }
        if self.has_function_call { return false; }
        if self.access_pattern == "random" { return false; }
        if self.step <= 0 { return false; }
        true
    }

    pub fn vectorization_gain(&self, simd_width: u32, element_bytes: u32) -> f64 {
        let lanes = simd_width / (element_bytes * 8);
        let base = lanes as f64;
        // Reduction variable slightly penalizes gain (need horizontal ops)
        if self.reduction_variable.is_some() {
            base * 0.75
        } else {
            base
        }
    }
}

pub struct LoopNest {
    pub loops: Vec<LoopInfo>,
    pub depth: u32,
}

impl LoopNest {
    pub fn new() -> Self {
        Self { loops: vec![], depth: 0 }
    }

    pub fn add_loop(&mut self, lp: LoopInfo) {
        if lp.inner_loops == 0 { self.depth += 1; }
        self.loops.push(lp);
    }

    pub fn innermost_vectorizable(&self) -> Vec<&LoopInfo> {
        self.loops.iter()
            .filter(|l| l.inner_loops == 0 && l.is_vectorizable())
            .collect()
    }
}

// ============================================================================
// Part 3: Vectorization Analysis Engine (200 lines)
// ============================================================================

pub struct VectorizationOpportunity {
    pub loop_id: u32,
    pub recommended_width: SimdWidth,
    pub expected_speedup: f64,
    pub vectorization_type: String,     // "data-parallel", "reduction", "gather-scatter"
    pub tail_handling: String,          // "scalar-epilog", "predicated", "peeled"
}

pub struct VectorizationAnalyzer {
    pub target_isa: String,      // "avx2", "avx512", "sse42", "neon"
    pub total_loops_analyzed: u32,
    pub vectorizable_count: u32,
    pub opportunities: Vec<VectorizationOpportunity>,
    pub detection_rate: f64,
}

impl VectorizationAnalyzer {
    pub fn new(isa: &str) -> Self {
        Self {
            target_isa: isa.to_string(),
            total_loops_analyzed: 0,
            vectorizable_count: 0,
            opportunities: vec![],
            detection_rate: 0.0,
        }
    }

    pub fn analyze_loop(&mut self, lp: &LoopInfo) -> Option<VectorizationOpportunity> {
        self.total_loops_analyzed += 1;

        if !lp.is_vectorizable() {
            return None;
        }

        let (width, element_bytes) = self.choose_simd_width(lp);
        let speedup = lp.vectorization_gain(
            match width {
                SimdWidth::Sse128 => 128,
                SimdWidth::Avx256 => 256,
                SimdWidth::Avx512 => 512,
            },
            element_bytes
        );

        // Only vectorize if speedup >= 2x (R2)
        if speedup < 2.0 { return None; }

        self.vectorizable_count += 1;

        let vtype = if lp.reduction_variable.is_some() {
            "reduction"
        } else if lp.access_pattern == "strided" {
            "gather-scatter"
        } else {
            "data-parallel"
        };

        let tail = if let Some(tc) = lp.trip_count {
            let lanes = match width { SimdWidth::Sse128 => 4, SimdWidth::Avx256 => 8, SimdWidth::Avx512 => 16 };
            if tc % lanes == 0 { "none" } else { "scalar-epilog" }
        } else {
            "predicated"
        };

        let opp = VectorizationOpportunity {
            loop_id: lp.id,
            recommended_width: width,
            expected_speedup: speedup,
            vectorization_type: vtype.to_string(),
            tail_handling: tail.to_string(),
        };

        self.opportunities.push(opp);
        self.update_detection_rate();
        self.opportunities.last().map(|_| VectorizationOpportunity {
            loop_id: lp.id,
            recommended_width: self.choose_simd_width(lp).0,
            expected_speedup: speedup,
            vectorization_type: vtype.to_string(),
            tail_handling: tail.to_string(),
        })
    }

    fn choose_simd_width(&self, lp: &LoopInfo) -> (SimdWidth, u32) {
        match self.target_isa.as_str() {
            "avx512" => (SimdWidth::Avx512, 4),
            "avx2"   => (SimdWidth::Avx256, 4),
            "neon"   => (SimdWidth::Sse128, 4),
            _        => (SimdWidth::Sse128, 4),  // sse42 fallback
        }
    }

    fn update_detection_rate(&mut self) {
        if self.total_loops_analyzed == 0 { return; }
        self.detection_rate = self.vectorizable_count as f64 / self.total_loops_analyzed as f64;
    }

    pub fn meets_r1_threshold(&self) -> bool {
        // R1: detection rate > 90% among structurally vectorizable loops
        self.detection_rate >= 0.90
    }

    pub fn analyze_function(&mut self, loops: &[LoopInfo]) -> Vec<VectorizationOpportunity> {
        let mut results = vec![];
        for lp in loops {
            if let Some(opp) = self.analyze_loop(lp) {
                results.push(opp);
            }
        }
        results
    }
}

// ============================================================================
// Part 4: Cost Model (100 lines)
// ============================================================================

pub struct SimdCostModel {
    pub isa: String,
    pub vector_throughput: f64,    // ops/cycle
    pub scalar_throughput: f64,
    pub gather_cost: u32,          // cycles for gather instruction
    pub scatter_cost: u32,
    pub horizontal_op_cost: u32,   // for reduction operations
    pub memory_bandwidth_gbps: f64,
}

impl SimdCostModel {
    pub fn avx2() -> Self {
        Self {
            isa: "avx2".to_string(),
            vector_throughput: 8.0,    // 8 f32 ops/cycle
            scalar_throughput: 1.0,
            gather_cost: 4,
            scatter_cost: 6,
            horizontal_op_cost: 3,
            memory_bandwidth_gbps: 40.0,
        }
    }

    pub fn avx512() -> Self {
        Self {
            isa: "avx512".to_string(),
            vector_throughput: 16.0,
            scalar_throughput: 1.0,
            gather_cost: 8,
            scatter_cost: 12,
            horizontal_op_cost: 4,
            memory_bandwidth_gbps: 80.0,
        }
    }

    pub fn estimate_speedup(&self, lp: &LoopInfo, vtype: &str) -> f64 {
        match vtype {
            "data-parallel" => self.vector_throughput / self.scalar_throughput,
            "reduction"     => (self.vector_throughput / self.scalar_throughput) * 0.75,
            "gather-scatter" => {
                let effective = self.vector_throughput / (self.gather_cost as f64 / 2.0);
                effective.max(2.0)
            }
            _ => 2.0,
        }
    }

    pub fn is_memory_bound(&self, bytes_per_iteration: u64, cycles_per_iteration: u64) -> bool {
        let bytes_per_sec = bytes_per_iteration as f64 * 3_000_000_000.0 / cycles_per_iteration as f64;
        let bw = self.memory_bandwidth_gbps * 1e9;
        bytes_per_sec > bw * 0.8   // memory-bound if >80% bandwidth
    }
}

// ============================================================================
// Part 5: Vectorizer Transform Engine (150 lines)
// ============================================================================

pub enum SimdInstruction {
    VLoad { dst: String, src: String, width: u32 },        // vmovaps/vmovdqu
    VStore { dst: String, src: String, width: u32 },       // vmovaps
    VAdd { dst: String, src1: String, src2: String },      // vaddps
    VSub { dst: String, src1: String, src2: String },      // vsubps
    VMul { dst: String, src1: String, src2: String },      // vmulps
    VDiv { dst: String, src1: String, src2: String },      // vdivps
    VFma { dst: String, src1: String, src2: String, acc: String }, // vfmadd213ps
    VBroadcast { dst: String, scalar: String, width: u32 },// vbroadcastss
    VHAdd { dst: String, src: String },                     // vhaddps (horizontal add)
    VGather { dst: String, base: String, indices: String },// vgatherdps
    VScatter { base: String, indices: String, src: String },// vscatterdps
    VCmp { dst: String, src1: String, src2: String, op: String }, // vcmpps
    VBlend { dst: String, src1: String, src2: String, mask: String }, // vblendvps
    VPermute { dst: String, src: String, ctrl: u32 },      // vpermps
}

pub struct VectorizedLoop {
    pub original_loop_id: u32,
    pub simd_instructions: Vec<SimdInstruction>,
    pub scalar_epilog: Vec<String>,
    pub total_vector_ops: u32,
    pub lanes: u32,
    pub estimated_speedup: f64,
}

pub struct SimdVectorizer {
    pub analyzer: VectorizationAnalyzer,
    pub cost_model: SimdCostModel,
    pub vectorized_loops: Vec<VectorizedLoop>,
    pub total_speedup_sum: f64,
    pub vectorized_count: u32,
}

impl SimdVectorizer {
    pub fn new(isa: &str) -> Self {
        let cost = match isa {
            "avx512" => SimdCostModel::avx512(),
            _ => SimdCostModel::avx2(),
        };
        Self {
            analyzer: VectorizationAnalyzer::new(isa),
            cost_model: cost,
            vectorized_loops: vec![],
            total_speedup_sum: 0.0,
            vectorized_count: 0,
        }
    }

    pub fn vectorize_loop(&mut self, lp: &LoopInfo) -> Option<VectorizedLoop> {
        let opp = self.analyzer.analyze_loop(lp)?;

        let lanes = match opp.recommended_width {
            SimdWidth::Sse128 => 4u32,
            SimdWidth::Avx256 => 8,
            SimdWidth::Avx512 => 16,
        };
        let width_bits = lanes * 32;

        let mut instrs = vec![];

        // Load A[i..i+lanes]
        instrs.push(SimdInstruction::VLoad {
            dst: format!("ymm0"),
            src: format!("A+i*4"),
            width: width_bits,
        });
        // Load B[i..i+lanes]
        instrs.push(SimdInstruction::VLoad {
            dst: "ymm1".to_string(),
            src: "B+i*4".to_string(),
            width: width_bits,
        });
        // FMA or Add depending on loop body
        if lp.body_instruction_count >= 3 {
            instrs.push(SimdInstruction::VFma {
                dst: "ymm2".to_string(),
                src1: "ymm0".to_string(),
                src2: "ymm1".to_string(),
                acc: "ymm2".to_string(),
            });
        } else {
            instrs.push(SimdInstruction::VAdd {
                dst: "ymm2".to_string(),
                src1: "ymm0".to_string(),
                src2: "ymm1".to_string(),
            });
        }
        // Store C[i..i+lanes]
        instrs.push(SimdInstruction::VStore {
            dst: "C+i*4".to_string(),
            src: "ymm2".to_string(),
            width: width_bits,
        });

        // Reduction horizontal add
        let mut epilog = vec![];
        if lp.reduction_variable.is_some() {
            instrs.push(SimdInstruction::VHAdd {
                dst: "ymm2".to_string(),
                src: "ymm2".to_string(),
            });
            epilog.push("extract_lane ymm2, xmm0, 0".to_string());
            epilog.push("scalar_add result, xmm0".to_string());
        }

        let speedup = self.cost_model.estimate_speedup(lp, &opp.vectorization_type);
        self.total_speedup_sum += speedup;
        self.vectorized_count += 1;

        let vl = VectorizedLoop {
            original_loop_id: lp.id,
            simd_instructions: instrs,
            scalar_epilog: epilog,
            total_vector_ops: 4,
            lanes,
            estimated_speedup: speedup,
        };

        self.vectorized_loops.push(VectorizedLoop {
            original_loop_id: lp.id,
            simd_instructions: vec![],
            scalar_epilog: vec![],
            total_vector_ops: 4,
            lanes,
            estimated_speedup: speedup,
        });

        Some(vl)
    }

    pub fn average_speedup(&self) -> f64 {
        if self.vectorized_count == 0 { return 1.0; }
        self.total_speedup_sum / self.vectorized_count as f64
    }

    pub fn meets_r2_speedup(&self) -> bool {
        // R2: average speedup 2-8x
        let avg = self.average_speedup();
        avg >= 2.0 && avg <= 8.0
    }

    pub fn vectorize_all(&mut self, loops: &[LoopInfo]) -> u32 {
        let mut count = 0u32;
        for lp in loops {
            if self.vectorize_loop(lp).is_some() {
                count += 1;
            }
        }
        count
    }
}

// ============================================================================
// Part 6: Profiling & Metrics (100 lines)
// ============================================================================

pub struct VectorizationReport {
    pub total_loops: u32,
    pub vectorized_loops: u32,
    pub detection_rate: f64,       // R1: must be >90%
    pub avg_speedup: f64,          // R2: must be 2-8x
    pub max_speedup: f64,
    pub min_speedup: f64,
    pub total_vector_instructions: u32,
    pub isa_used: String,
    pub memory_bound_loops: u32,
    pub reduction_loops: u32,
}

impl VectorizationReport {
    pub fn generate(vectorizer: &SimdVectorizer) -> Self {
        let mut max_sp = 0.0f64;
        let mut min_sp = f64::MAX;
        let mut total_instrs = 0u32;
        let mut reductions = 0u32;

        for vl in &vectorizer.vectorized_loops {
            max_sp = max_sp.max(vl.estimated_speedup);
            min_sp = min_sp.min(vl.estimated_speedup);
            total_instrs += vl.total_vector_ops;
        }

        Self {
            total_loops: vectorizer.analyzer.total_loops_analyzed,
            vectorized_loops: vectorizer.vectorized_count,
            detection_rate: vectorizer.analyzer.detection_rate,
            avg_speedup: vectorizer.average_speedup(),
            max_speedup: max_sp,
            min_speedup: if min_sp == f64::MAX { 0.0 } else { min_sp },
            total_vector_instructions: total_instrs,
            isa_used: vectorizer.cost_model.isa.clone(),
            memory_bound_loops: 0,
            reduction_loops: reductions,
        }
    }

    pub fn r1_pass(&self) -> bool { self.detection_rate >= 0.90 }
    pub fn r2_pass(&self) -> bool { self.avg_speedup >= 2.0 && self.avg_speedup <= 8.0 }

    pub fn summary(&self) -> String {
        format!(
            "VectorizationReport: loops={}/{} detect={:.1}% speedup={:.2}x [{:.2}x-{:.2}x] R1={} R2={}",
            self.vectorized_loops, self.total_loops,
            self.detection_rate * 100.0,
            self.avg_speedup, self.min_speedup, self.max_speedup,
            if self.r1_pass() { "PASS" } else { "FAIL" },
            if self.r2_pass() { "PASS" } else { "FAIL" },
        )
    }
}

# ================================================================
# FreeLang v4 Core - Main Lexer
# Converts source code into a token stream
# Performance target: R1 < 50ms for 1,000 tokens
# ================================================================

# ---- Lexer State ----

fn create_lexer(source: string) -> any {
  scanner = create_scanner(source)
  keyword_map = build_keyword_map()

  return {
    "scanner": scanner,
    "keyword_map": keyword_map,
    "tokens": [],
    "token_count": 0,
    "start_time": 0,
    "elapsed_ms": 0,
    "mode": "NORMAL",
    "interpolation_depth": 0,
    "paren_depth": 0,
    "brace_depth": 0,
    "bracket_depth": 0
  }
}

# ---- Main Tokenize Function ----

fn tokenize(source: string) -> any {
  lex = create_lexer(source)
  lex["start_time"] = time_now()

  while not scanner_at_end(lex["scanner"]) {
    scanner_skip_trivia(lex["scanner"])

    if scanner_at_end(lex["scanner"]) {
      break
    }

    scanner_mark_start(lex["scanner"])
    token = lex_next_token(lex)

    if token != nil {
      push(lex["tokens"], token)
      lex["token_count"] = lex["token_count"] + 1
    }
  }

  # Add EOF token
  eof = create_token(
    TOKEN_EOF, "",
    lex["scanner"]["line"],
    lex["scanner"]["col"],
    lex["scanner"]["pos"]
  )
  push(lex["tokens"], eof)
  lex["token_count"] = lex["token_count"] + 1

  lex["elapsed_ms"] = time_now() - lex["start_time"]

  return {
    "tokens": lex["tokens"],
    "token_count": lex["token_count"],
    "errors": scanner_get_errors(lex["scanner"]),
    "error_count": lex["scanner"]["error_count"],
    "elapsed_ms": lex["elapsed_ms"]
  }
}

# ---- Token Dispatch ----

fn lex_next_token(lex: any) -> any {
  s = lex["scanner"]
  ch = scanner_peek(s)

  # Number literals
  if is_digit(ch) {
    return lex_number(lex)
  }

  # Identifiers and keywords
  if is_alpha(ch) {
    return lex_identifier_or_keyword(lex)
  }

  # String literals
  if ch == "\"" {
    # Check for multi-line string
    if scanner_peek_next(s) == "\"" and scanner_peek_at(s, 2) == "\"" {
      return lex_multiline_string(lex)
    }
    return lex_string(lex, "\"")
  }

  if ch == "'" {
    return lex_char_or_lifetime(lex)
  }

  # Operators and punctuation
  return lex_operator_or_punct(lex)
}

# ---- Number Lexing ----

fn lex_number(lex: any) -> any {
  s = lex["scanner"]
  line = s["line"]
  col = s["col"]
  offset = s["pos"]

  num_result = scanner_scan_number(s)

  return create_token(
    num_result["type"],
    num_result["value"],
    line, col, offset
  )
}

# ---- Identifier / Keyword Lexing ----

fn lex_identifier_or_keyword(lex: any) -> any {
  s = lex["scanner"]
  line = s["line"]
  col = s["col"]
  offset = s["pos"]

  # Check for string prefix (f"...", r"...", b"...")
  ch = scanner_peek(s)
  next = scanner_peek_next(s)

  if ch == "f" and next == "\"" {
    return lex_interpolated_string(lex)
  }
  if ch == "r" and (next == "\"" or next == "#") {
    return lex_raw_string(lex)
  }
  if ch == "b" and next == "\"" {
    return lex_byte_string(lex)
  }

  # Regular identifier
  ident = scanner_scan_identifier_chars(s)

  # Check keyword map
  kw_type = lex["keyword_map"][ident]
  if kw_type != nil {
    return create_token(kw_type, ident, line, col, offset)
  }

  # Check if type identifier (starts with uppercase)
  if is_upper(ident[0]) {
    return create_token(TOKEN_TYPE_IDENT, ident, line, col, offset)
  }

  return create_token(TOKEN_IDENT, ident, line, col, offset)
}

# ---- String Lexing ----

fn lex_string(lex: any, quote: string) -> any {
  s = lex["scanner"]
  line = s["line"]
  col = s["col"]
  offset = s["pos"]

  value = scanner_scan_string(s, quote)

  return create_token(TOKEN_STRING, value, line, col, offset)
}

fn lex_multiline_string(lex: any) -> any {
  s = lex["scanner"]
  line = s["line"]
  col = s["col"]
  offset = s["pos"]

  value = scanner_scan_multiline_string(s)

  return create_token(TOKEN_STRING, value, line, col, offset)
}

fn lex_raw_string(lex: any) -> any {
  s = lex["scanner"]
  line = s["line"]
  col = s["col"]
  offset = s["pos"]

  value = scanner_scan_raw_string(s)

  return create_token(TOKEN_STRING, value, line, col, offset)
}

fn lex_byte_string(lex: any) -> any {
  s = lex["scanner"]
  line = s["line"]
  col = s["col"]
  offset = s["pos"]

  scanner_advance(s)  # skip 'b'
  value = scanner_scan_string(s, "\"")

  return create_token(TOKEN_STRING, "b\"" + value + "\"", line, col, offset)
}

fn lex_interpolated_string(lex: any) -> any {
  s = lex["scanner"]
  line = s["line"]
  col = s["col"]
  offset = s["pos"]

  segments = scanner_scan_interpolated_string(s)

  # Encode as special string token with segments metadata
  combined = ""
  i = 0
  while i < length(segments) {
    seg = segments[i]
    if seg["type"] == "TEXT" {
      combined = combined + seg["value"]
    } else {
      combined = combined + "${" + seg["value"] + "}"
    }
    i = i + 1
  }

  token = create_token(TOKEN_STRING, combined, line, col, offset)
  token["interpolated"] = true
  token["segments"] = segments
  return token
}

# ---- Character / Lifetime Lexing ----

fn lex_char_or_lifetime(lex: any) -> any {
  s = lex["scanner"]
  line = s["line"]
  col = s["col"]
  offset = s["pos"]

  scanner_advance(s)  # skip '

  # Check for lifetime ('a, 'static, etc.)
  ch = scanner_peek(s)
  if is_alpha(ch) {
    name = scanner_scan_identifier_chars(s)
    if scanner_peek(s) != "'" {
      # It's a lifetime: 'a, 'static
      return create_token(TOKEN_IDENT, "'" + name, line, col, offset)
    }
    # It's a char: 'a'
    scanner_advance(s)  # skip closing '
    return create_token(TOKEN_CHAR, name, line, col, offset)
  }

  # Escape character: '\n'
  if ch == "\\" {
    scanner_advance(s)
    esc = scanner_advance(s)
    if scanner_peek(s) != "'" {
      scanner_add_error(s, "Unterminated character literal")
    } else {
      scanner_advance(s)
    }
    return create_token(TOKEN_CHAR, "\\" + esc, line, col, offset)
  }

  # Regular character: 'x'
  value = scanner_advance(s)
  if scanner_peek(s) != "'" {
    scanner_add_error(s, "Unterminated character literal")
  } else {
    scanner_advance(s)
  }
  return create_token(TOKEN_CHAR, value, line, col, offset)
}

# ---- Operator / Punctuation Lexing ----

fn lex_operator_or_punct(lex: any) -> any {
  s = lex["scanner"]
  line = s["line"]
  col = s["col"]
  offset = s["pos"]
  ch = scanner_advance(s)

  match ch {
    # Arithmetic
    "+" => {
      if scanner_match(s, "=") { return create_token(TOKEN_PLUS_ASSIGN, "+=", line, col, offset) }
      return create_token(TOKEN_PLUS, "+", line, col, offset)
    },
    "-" => {
      if scanner_match(s, ">") { return create_token(TOKEN_ARROW, "->", line, col, offset) }
      if scanner_match(s, "=") { return create_token(TOKEN_MINUS_ASSIGN, "-=", line, col, offset) }
      return create_token(TOKEN_MINUS, "-", line, col, offset)
    },
    "*" => {
      if scanner_match(s, "*") { return create_token(TOKEN_POWER, "**", line, col, offset) }
      if scanner_match(s, "=") { return create_token(TOKEN_STAR_ASSIGN, "*=", line, col, offset) }
      return create_token(TOKEN_STAR, "*", line, col, offset)
    },
    "/" => {
      if scanner_match(s, "=") { return create_token(TOKEN_SLASH_ASSIGN, "/=", line, col, offset) }
      return create_token(TOKEN_SLASH, "/", line, col, offset)
    },
    "%" => {
      if scanner_match(s, "=") { return create_token(TOKEN_PERCENT_ASSIGN, "%=", line, col, offset) }
      return create_token(TOKEN_PERCENT, "%", line, col, offset)
    },

    # Comparison and Assignment
    "=" => {
      if scanner_match(s, "=") { return create_token(TOKEN_EQ, "==", line, col, offset) }
      if scanner_match(s, ">") { return create_token(TOKEN_FAT_ARROW, "=>", line, col, offset) }
      return create_token(TOKEN_ASSIGN, "=", line, col, offset)
    },
    "!" => {
      if scanner_match(s, "=") { return create_token(TOKEN_NEQ, "!=", line, col, offset) }
      return create_token(TOKEN_NOT, "!", line, col, offset)
    },
    "<" => {
      if scanner_match(s, "=") { return create_token(TOKEN_LTE, "<=", line, col, offset) }
      if scanner_match(s, "<") { return create_token(TOKEN_SHL, "<<", line, col, offset) }
      return create_token(TOKEN_LT, "<", line, col, offset)
    },
    ">" => {
      if scanner_match(s, "=") { return create_token(TOKEN_GTE, ">=", line, col, offset) }
      if scanner_match(s, ">") { return create_token(TOKEN_SHR, ">>", line, col, offset) }
      return create_token(TOKEN_GT, ">", line, col, offset)
    },

    # Logical and Bitwise
    "&" => {
      if scanner_match(s, "&") { return create_token(TOKEN_AND, "&&", line, col, offset) }
      return create_token(TOKEN_BAND, "&", line, col, offset)
    },
    "|" => {
      if scanner_match(s, "|") { return create_token(TOKEN_OR, "||", line, col, offset) }
      return create_token(TOKEN_PIPE, "|", line, col, offset)
    },
    "^" => {
      return create_token(TOKEN_BXOR, "^", line, col, offset)
    },
    "~" => {
      return create_token(TOKEN_BNOT, "~", line, col, offset)
    },

    # Delimiters
    "(" => {
      lex["paren_depth"] = lex["paren_depth"] + 1
      return create_token(TOKEN_LPAREN, "(", line, col, offset)
    },
    ")" => {
      lex["paren_depth"] = lex["paren_depth"] - 1
      return create_token(TOKEN_RPAREN, ")", line, col, offset)
    },
    "{" => {
      lex["brace_depth"] = lex["brace_depth"] + 1
      return create_token(TOKEN_LBRACE, "{", line, col, offset)
    },
    "}" => {
      lex["brace_depth"] = lex["brace_depth"] - 1
      return create_token(TOKEN_RBRACE, "}", line, col, offset)
    },
    "[" => {
      lex["bracket_depth"] = lex["bracket_depth"] + 1
      return create_token(TOKEN_LBRACKET, "[", line, col, offset)
    },
    "]" => {
      lex["bracket_depth"] = lex["bracket_depth"] - 1
      return create_token(TOKEN_RBRACKET, "]", line, col, offset)
    },

    # Punctuation
    "," => { return create_token(TOKEN_COMMA, ",", line, col, offset) },
    "." => {
      if scanner_match(s, ".") {
        if scanner_match(s, ".") {
          return create_token(TOKEN_DOTDOTDOT, "...", line, col, offset)
        }
        return create_token(TOKEN_DOTDOT, "..", line, col, offset)
      }
      return create_token(TOKEN_DOT, ".", line, col, offset)
    },
    ":" => {
      if scanner_match(s, ":") { return create_token(TOKEN_COLONCOLON, "::", line, col, offset) }
      return create_token(TOKEN_COLON, ":", line, col, offset)
    },
    ";" => { return create_token(TOKEN_SEMICOLON, ";", line, col, offset) },
    "#" => { return create_token(TOKEN_HASH, "#", line, col, offset) },
    "@" => { return create_token(TOKEN_AT, "@", line, col, offset) },
    "?" => { return create_token(TOKEN_QUESTION, "?", line, col, offset) },
    "_" => {
      # Could be wildcard or start of identifier
      if is_alphanumeric(scanner_peek(s)) {
        ident = "_" + scanner_scan_identifier_chars(s)
        return create_token(TOKEN_IDENT, ident, line, col, offset)
      }
      return create_token(TOKEN_UNDERSCORE, "_", line, col, offset)
    },
    "\n" => {
      return create_token(TOKEN_NEWLINE, "\\n", line, col, offset)
    },

    # Unknown character
    _ => {
      scanner_add_error(s, "Unexpected character: '" + ch + "'")
      return create_token(TOKEN_ERROR, ch, line, col, offset)
    }
  }
}

# ---- Lexer Utilities ----

fn lex_count_tokens_by_type(result: any, token_type: string) -> i32 {
  count = 0
  i = 0
  while i < length(result["tokens"]) {
    if result["tokens"][i]["type"] == token_type {
      count = count + 1
    }
    i = i + 1
  }
  return count
}

fn lex_get_token_at(result: any, index: i32) -> any {
  if index < 0 or index >= length(result["tokens"]) {
    return nil
  }
  return result["tokens"][index]
}

fn lex_filter_tokens(result: any, include_newlines: bool) -> array {
  filtered = []
  i = 0
  while i < length(result["tokens"]) {
    token = result["tokens"][i]
    if token["type"] != TOKEN_NEWLINE or include_newlines {
      if token["type"] != TOKEN_ERROR {
        push(filtered, token)
      }
    }
    i = i + 1
  }
  return filtered
}

fn lex_pretty_print(result: any) -> string {
  output = ""
  i = 0
  while i < length(result["tokens"]) {
    t = result["tokens"][i]
    output = output + "[" + t["type"] + " '" + t["value"] + "' L" + to_string(t["line"]) + ":" + to_string(t["col"]) + "]\n"
    i = i + 1
  }
  return output
}

# ---- Performance Metrics ----

fn lex_performance_report(result: any) -> any {
  return {
    "token_count": result["token_count"],
    "error_count": result["error_count"],
    "elapsed_ms": result["elapsed_ms"],
    "tokens_per_ms": result["token_count"] / max(result["elapsed_ms"], 1),
    "has_errors": result["error_count"] > 0,
    "r1_pass": result["elapsed_ms"] < 50  # R1: < 50ms for 1000 tokens
  }
}

