// ============================================================================

fn reverse_lookup(registry_data: dict, ip: string) -> array {
  var result = []
  var k = keys(registry_data)
  var i = 0
  while i < length(k) {
    var domain = k[i]
    var rec_str = registry_data[domain]
    var parts = split_pipe(rec_str)
    if length(parts) >= 3 {
      if parts[2] == ip {
        result = push(result, domain)
      }
    }
    i = i + 1
  }
  return result
}

// ============================================================================
// Utilities
// ============================================================================

fn split_pipe(s: string) -> array {
  var result = []
  var current = ""
  var i = 0
  while i < length(s) {
    var c = substr(s, i, 1)
    if c == "|" {
      result = push(result, current)
      current = ""
    } else {
      current = current + c
    }
    i = i + 1
  }
  result = push(result, current)
  return result
}

fn str_to_int(s: string) -> i32 {
  var result = 0
  var i = 0
  while i < length(s) {
    var c = substr(s, i, 1)
    if c >= "0" && c <= "9" {
      result = result * 10 + char_to_digit(c)
    }
    i = i + 1
  }
  return result
}

fn char_to_digit(c: string) -> i32 {
  if c == "0" { return 0 }
  if c == "1" { return 1 }
  if c == "2" { return 2 }
  if c == "3" { return 3 }
  if c == "4" { return 4 }
  if c == "5" { return 5 }
  if c == "6" { return 6 }
  if c == "7" { return 7 }
  if c == "8" { return 8 }
  if c == "9" { return 9 }
  return 0
}

fn current_time_ms() -> i64 {
  return 1000000
}

fn to_string(n: i64) -> string {
  if n == 0 { return "0" }
  var result = ""
  var v = n
  var neg = false
  if v < 0 {
    v = -v
    neg = true
  }
  while v > 0 {
    var d = v % 10
    var dc = "0"
    if d == 1 { dc = "1" }
    if d == 2 { dc = "2" }
    if d == 3 { dc = "3" }
    if d == 4 { dc = "4" }
    if d == 5 { dc = "5" }
    if d == 6 { dc = "6" }
    if d == 7 { dc = "7" }
    if d == 8 { dc = "8" }
    if d == 9 { dc = "9" }
    result = dc + result
    v = v / 10
  }
  if neg { return "-" + result }
  return result
}

