struct TestResult {
  name: string,
  passed: bool,
  latency_ms: i64,
  message: string
}

struct TestSuite {
  results: array,
  passed: i32,
  failed: i32,
  total: i32
}

fn suite_new() -> TestSuite {
  return TestSuite {
    results: [],
    passed: 0,
    failed: 0,
    total: 0
  }
}

fn suite_add(suite: TestSuite, result: TestResult) -> TestSuite {
  var new_results = push(suite.results, result)
  var new_passed = suite.passed
  var new_failed = suite.failed
  if result.passed {
    new_passed = new_passed + 1
  } else {
    new_failed = new_failed + 1
  }
  return TestSuite {
    results: new_results,
    passed: new_passed,
    failed: new_failed,
    total: suite.total + 1
  }
}

fn make_pass(name: string, latency: i64, msg: string) -> TestResult {
  return TestResult {
    name: name,
    passed: true,
    latency_ms: latency,
    message: msg
  }
}

fn make_fail(name: string, latency: i64, msg: string) -> TestResult {
  return TestResult {
    name: name,
    passed: false,
    latency_ms: latency,
    message: msg
  }
}

