fn ends_with(s: string, suffix: string) -> bool {
  var sl = length(s)
  var pl = length(suffix)
  if sl < pl { return false }
  var i = 0
  while i < pl {
    if substr(s, sl - pl + i, 1) != substr(suffix, i, 1) { return false }
    i = i + 1
  }
  return true
}

