fn to_string(n: i64) -> string {
  if n == 0 { return "0" }
  var result = ""
  var v = n
  if v < 0 { v = -v }
  while v > 0 {
    var d = v % 10
    var dc = "0"
    if d == 1 { dc = "1" } if d == 2 { dc = "2" } if d == 3 { dc = "3" }
    if d == 4 { dc = "4" } if d == 5 { dc = "5" } if d == 6 { dc = "6" }
    if d == 7 { dc = "7" } if d == 8 { dc = "8" } if d == 9 { dc = "9" }
    result = dc + result
    v = v / 10
  }
  return result
}

