# ---- Scope Management ----

fn tc_push_scope(tc: any) -> any {
  push(tc["scopes"], {})
  tc["scope_depth"] = tc["scope_depth"] + 1
  return tc
}

fn tc_pop_scope(tc: any) -> any {
  pop(tc["scopes"])
  tc["scope_depth"] = tc["scope_depth"] - 1
  return tc
}

fn tc_define(tc: any, name: string, type_info: any) -> any {
  current_scope = tc["scopes"][tc["scope_depth"]]
  current_scope[name] = type_info
  return tc
}

fn tc_lookup(tc: any, name: string) -> any {
  # Search from innermost scope outward
  depth = tc["scope_depth"]
  while depth >= 0 {
    scope = tc["scopes"][depth]
    if scope[name] != nil {
      return scope[name]
    }
    depth = depth - 1
  }
  return nil
}

fn tc_define_type(tc: any, name: string, type_def: any) -> any {
  tc["type_defs"][name] = type_def
  return tc
}

fn tc_lookup_type(tc: any, name: string) -> any {
  return tc["type_defs"][name]
}

fn tc_define_trait(tc: any, name: string, trait_def: any) -> any {
  tc["trait_defs"][name] = trait_def
  return tc
}

fn tc_add_impl(tc: any, impl_def: any) -> any {
  push(tc["impl_defs"], impl_def)
  return tc
}

# ---- Error Reporting ----

fn tc_error(tc: any, message: string, span: any) -> any {
  err = {
    "message": message,
    "line": span["line"],
    "col": span["col"]
  }
  push(tc["errors"], err)
  tc["error_count"] = tc["error_count"] + 1
  return tc
}

fn tc_warning(tc: any, message: string, span: any) -> any {
  push(tc["warnings"], { "message": message, "line": span["line"], "col": span["col"] })
  return tc
}

# ---- Type Inference ----

fn tc_fresh_type_var(tc: any) -> any {
  tc["infer_counter"] = tc["infer_counter"] + 1
  return type_infer(tc["infer_counter"])
}

fn tc_unify(tc: any, t1: any, t2: any, span: any) -> bool {
  # Resolve type variables
  t1 = tc_resolve(tc, t1)
  t2 = tc_resolve(tc, t2)

  if t1 == nil or t2 == nil {
    return true  # Allow nil (unknown) to unify
  }

  # Same type
  if t1["kind"] == t2["kind"] and t1["name"] == t2["name"] {
    return true
  }

  # Infer variable
  if t1["kind"] == TYPE_INFER {
    tc["substitutions"][to_string(t1["infer_id"])] = t2
    return true
  }
  if t2["kind"] == TYPE_INFER {
    tc["substitutions"][to_string(t2["infer_id"])] = t1
    return true
  }

  # Any type matches everything
  if t1["kind"] == TYPE_ANY or t2["kind"] == TYPE_ANY {
    return true
  }

  # Never type is a subtype of everything
  if t1["kind"] == TYPE_NEVER or t2["kind"] == TYPE_NEVER {
    return true
  }

  # Numeric coercion: i32 -> i64, f32 -> f64
  if t1["is_numeric"] and t2["is_numeric"] {
    if type_can_coerce(t1, t2) {
      return true
    }
  }

  # Array element type unification
  if t1["kind"] == TYPE_ARRAY and t2["kind"] == TYPE_ARRAY {
    return tc_unify(tc, t1["element_type"], t2["element_type"], span)
  }

  # Function type unification
  if t1["kind"] == TYPE_FN and t2["kind"] == TYPE_FN {
    if length(t1["param_types"]) != length(t2["param_types"]) {
      tc_error(tc, "Function parameter count mismatch", span)
      return false
    }
    i = 0
    while i < length(t1["param_types"]) {
      if not tc_unify(tc, t1["param_types"][i], t2["param_types"][i], span) {
        return false
      }
      i = i + 1
    }
    return tc_unify(tc, t1["return_type"], t2["return_type"], span)
  }

  # Option unification
  if t1["kind"] == TYPE_OPTION and t2["kind"] == TYPE_OPTION {
    return tc_unify(tc, t1["inner_type"], t2["inner_type"], span)
  }

  # Result unification
  if t1["kind"] == TYPE_RESULT and t2["kind"] == TYPE_RESULT {
    return tc_unify(tc, t1["ok_type"], t2["ok_type"], span) and
           tc_unify(tc, t1["err_type"], t2["err_type"], span)
  }

  # Ref unification
  if (t1["kind"] == TYPE_REF or t1["kind"] == TYPE_MUT_REF) and
     (t2["kind"] == TYPE_REF or t2["kind"] == TYPE_MUT_REF) {
    return tc_unify(tc, t1["inner_type"], t2["inner_type"], span)
  }

  tc_error(tc, "Type mismatch: expected " + type_to_string(t1) + ", got " + type_to_string(t2), span)
  return false
}

fn tc_resolve(tc: any, t: any) -> any {
  if t == nil {
    return nil
  }
  if t["kind"] == TYPE_INFER {
    resolved = tc["substitutions"][to_string(t["infer_id"])]
    if resolved != nil {
      return tc_resolve(tc, resolved)
    }
  }
  return t
}

# ---- Type Coercion Rules ----

fn type_can_coerce(from: any, to: any) -> bool {
  if from["kind"] == to["kind"] {
    return true
  }

  # Widening: i8 -> i16 -> i32 -> i64
  if from["is_integer"] and to["is_integer"] and to["size"] >= from["size"] {
    if from["is_signed"] == to["is_signed"] or (not from["is_signed"] and to["is_signed"]) {
      return true
    }
  }

  # Float widening: f32 -> f64
  if from["is_float"] and to["is_float"] and to["size"] >= from["size"] {
    return true
  }

  # Integer to float
  if from["is_integer"] and to["is_float"] {
    return true
  }

  return false
}

# ---- AST Type Checking ----

fn check_program(tc: any, program: any) -> any {
  # Register built-in types
  tc_define(tc, "i8", type_primitive("i8"))
  tc_define(tc, "i16", type_primitive("i16"))
  tc_define(tc, "i32", type_primitive("i32"))
  tc_define(tc, "i64", type_primitive("i64"))
  tc_define(tc, "u8", type_primitive("u8"))
  tc_define(tc, "u16", type_primitive("u16"))
  tc_define(tc, "u32", type_primitive("u32"))
  tc_define(tc, "u64", type_primitive("u64"))
  tc_define(tc, "f32", type_primitive("f32"))
  tc_define(tc, "f64", type_primitive("f64"))
  tc_define(tc, "bool", type_primitive("bool"))
  tc_define(tc, "char", type_primitive("char"))
  tc_define(tc, "string", type_primitive("string"))
  tc_define(tc, "void", type_primitive("void"))

  # Check all declarations
  i = 0
  while i < length(program["declarations"]) {
    check_declaration(tc, program["declarations"][i])
    i = i + 1
  }

  return tc
}

fn check_declaration(tc: any, decl: any) -> any {
  tc["checked_count"] = tc["checked_count"] + 1
  kind = decl["kind"]

  match kind {
    AST_FN_DECL      => { return check_fn_decl(tc, decl) },
    AST_LET_DECL     => { return check_let_decl(tc, decl) },
    AST_CONST_DECL   => { return check_const_decl(tc, decl) },
    AST_STRUCT_DECL  => { return check_struct_decl(tc, decl) },
    AST_ENUM_DECL    => { return check_enum_decl(tc, decl) },
    AST_TRAIT_DECL   => { return check_trait_decl(tc, decl) },
    AST_IMPL_DECL    => { return check_impl_decl(tc, decl) },
    AST_EXPR_STMT    => { return check_expr(tc, decl["expr"]) },
    AST_RETURN_STMT  => { return check_return_stmt(tc, decl) },
    AST_ASSIGNMENT   => { return check_assignment(tc, decl) },
    AST_BLOCK        => { return check_block(tc, decl) },
    _ => { return nil }
  }
}

fn check_fn_decl(tc: any, decl: any) -> any {
  # Build function type from parameters and return type
  param_types = []
  i = 0
  while i < length(decl["params"]) {
    p = decl["params"][i]
    pt = nil
    if p["type_ann"] != nil {
      pt = resolve_type_annotation(tc, p["type_ann"])
    } else {
      pt = tc_fresh_type_var(tc)
    }
    push(param_types, pt)
    i = i + 1
  }

  ret_type = nil
  if decl["return_type"] != nil {
    ret_type = resolve_type_annotation(tc, decl["return_type"])
  } else {
    ret_type = tc_fresh_type_var(tc)
  }

  fn_type = type_fn(param_types, ret_type)
  tc_define(tc, decl["name"], fn_type)

  # Check body in new scope
  tc_push_scope(tc)

  # Define params in scope
  i = 0
  while i < length(decl["params"]) {
    p = decl["params"][i]
    tc_define(tc, p["name"], param_types[i])
    i = i + 1
  }

  # Check body
  if decl["body"] != nil {
    body_type = check_block(tc, decl["body"])
    # Unify body type with declared return type
    if ret_type != nil and body_type != nil {
      tc_unify(tc, ret_type, body_type, decl["span"])
    }
  }

  tc_pop_scope(tc)
  decl["type_info"] = fn_type
  return fn_type
}

fn check_let_decl(tc: any, decl: any) -> any {
  declared_type = nil
  if decl["type_ann"] != nil {
    declared_type = resolve_type_annotation(tc, decl["type_ann"])
  }

  value_type = nil
  if decl["value"] != nil {
    value_type = check_expr(tc, decl["value"])
  }

  final_type = nil
  if declared_type != nil and value_type != nil {
    tc_unify(tc, declared_type, value_type, decl["span"])
    final_type = declared_type
  } else if declared_type != nil {
    final_type = declared_type
  } else if value_type != nil {
    final_type = value_type
  } else {
    final_type = tc_fresh_type_var(tc)
  }

  tc_define(tc, decl["name"], final_type)
  decl["type_info"] = final_type
  return final_type
}

fn check_const_decl(tc: any, decl: any) -> any {
  value_type = check_expr(tc, decl["value"])
  if decl["type_ann"] != nil {
    declared_type = resolve_type_annotation(tc, decl["type_ann"])
    tc_unify(tc, declared_type, value_type, decl["span"])
    tc_define(tc, decl["name"], declared_type)
    return declared_type
  }
  tc_define(tc, decl["name"], value_type)
  return value_type
}

fn check_struct_decl(tc: any, decl: any) -> any {
  fields = []
  i = 0
  while i < length(decl["fields"]) {
    f = decl["fields"][i]
    ft = resolve_type_annotation(tc, f["type_ann"])
    push(fields, { "name": f["name"], "type": ft })
    i = i + 1
  }
  struct_type = type_struct(decl["name"], fields)
  tc_define_type(tc, decl["name"], struct_type)
  tc_define(tc, decl["name"], struct_type)
  return struct_type
}

fn check_enum_decl(tc: any, decl: any) -> any {
  variants = []
  i = 0
  while i < length(decl["variants"]) {
    v = decl["variants"][i]
    v_types = []
    if v["fields"] != nil {
      j = 0
      while j < length(v["fields"]) {
        push(v_types, resolve_type_annotation(tc, v["fields"][j]))
        j = j + 1
      }
    }
    push(variants, { "name": v["name"], "types": v_types })
    i = i + 1
  }
  enum_type = type_enum(decl["name"], variants)
  tc_define_type(tc, decl["name"], enum_type)
  tc_define(tc, decl["name"], enum_type)
  return enum_type
}

fn check_trait_decl(tc: any, decl: any) -> any {
  tc_define_trait(tc, decl["name"], decl)
  return nil
}

fn check_impl_decl(tc: any, decl: any) -> any {
  tc_add_impl(tc, decl)
  tc_push_scope(tc)

  # Check all methods
  i = 0
  while i < length(decl["methods"]) {
    check_fn_decl(tc, decl["methods"][i])
    i = i + 1
  }

  tc_pop_scope(tc)
  return nil
}

fn check_block(tc: any, block: any) -> any {
  if block == nil {
    return type_primitive("void")
  }

  tc_push_scope(tc)
  last_type = type_primitive("void")

  i = 0
  while i < length(block["statements"]) {
    last_type = check_declaration(tc, block["statements"][i])
    i = i + 1
  }

  tc_pop_scope(tc)
  return last_type
}

fn check_return_stmt(tc: any, stmt: any) -> any {
  if stmt["value"] != nil {
    return check_expr(tc, stmt["value"])
  }
  return type_primitive("void")
}

fn check_assignment(tc: any, stmt: any) -> any {
  target_type = check_expr(tc, stmt["target"])
  value_type = check_expr(tc, stmt["value"])
  tc_unify(tc, target_type, value_type, stmt["span"])
  return type_primitive("void")
}

# ---- Expression Type Checking ----

fn check_expr(tc: any, expr: any) -> any {
  if expr == nil {
    return nil
  }
  tc["checked_count"] = tc["checked_count"] + 1
  kind = expr["kind"]

  match kind {
    AST_LITERAL => {
      return check_literal(tc, expr)
    },
    AST_IDENT => {
      result = tc_lookup(tc, expr["name"])
      if result == nil {
        tc_error(tc, "Undefined variable: " + expr["name"], expr["span"])
        return tc_fresh_type_var(tc)
      }
      expr["type_info"] = result
      return result
    },
    AST_BINARY => {
      return check_binary(tc, expr)
    },
    AST_UNARY => {
      return check_unary(tc, expr)
    },
    AST_CALL => {
      return check_call(tc, expr)
    },
    AST_METHOD_CALL => {
      return check_method_call(tc, expr)
    },
    AST_FIELD_ACCESS => {
      return check_field_access(tc, expr)
    },
    AST_INDEX => {
      return check_index(tc, expr)
    },
    AST_IF_EXPR => {
      return check_if_expr(tc, expr)
    },
    AST_MATCH_EXPR => {
      return check_match_expr(tc, expr)
    },
    AST_BLOCK => {
      return check_block(tc, expr)
    },
    AST_ARRAY_LITERAL => {
      return check_array_literal(tc, expr)
    },
    AST_WHILE_EXPR => {
      check_expr(tc, expr["condition"])
      check_block(tc, expr["body"])
      return type_primitive("void")
    },
    AST_FOR_EXPR => {
      tc_push_scope(tc)
      iter_type = check_expr(tc, expr["iterable"])
      tc_define(tc, expr["variable"], tc_fresh_type_var(tc))
      check_block(tc, expr["body"])
      tc_pop_scope(tc)
      return type_primitive("void")
    },
    AST_CLOSURE => {
      return check_closure(tc, expr)
    },
    AST_ASYNC_EXPR => {
      body_type = check_block(tc, expr["body"])
      return body_type
    },
    AST_AWAIT_EXPR => {
      return check_expr(tc, expr["expr"])
    },
    AST_TRY_EXPR => {
      return check_expr(tc, expr["expr"])
    },
    _ => {
      return tc_fresh_type_var(tc)
    }
  }
}

fn check_literal(tc: any, expr: any) -> any {
  result = nil
  match expr["lit_type"] {
    "integer" => { result = type_primitive("i32") },
    "float"   => { result = type_primitive("f64") },
    "string"  => { result = type_primitive("string") },
    "char"    => { result = type_primitive("char") },
    "bool"    => { result = type_primitive("bool") },
    "nil"     => { result = type_primitive("nil") },
    _ => { result = tc_fresh_type_var(tc) }
  }
  expr["type_info"] = result
  return result
}

fn check_binary(tc: any, expr: any) -> any {
  left_type = check_expr(tc, expr["left"])
  right_type = check_expr(tc, expr["right"])
  op = expr["op"]

  # Comparison operators return bool
  if op == "==" or op == "!=" or op == "<" or op == ">" or op == "<=" or op == ">=" {
    tc_unify(tc, left_type, right_type, expr["span"])
    result = type_primitive("bool")
    expr["type_info"] = result
    return result
  }

  # Logical operators
  if op == "&&" or op == "||" {
    tc_unify(tc, left_type, type_primitive("bool"), expr["span"])
    tc_unify(tc, right_type, type_primitive("bool"), expr["span"])
    result = type_primitive("bool")
    expr["type_info"] = result
    return result
  }

  # String concatenation
  if op == "+" and left_type != nil and left_type["kind"] == TYPE_STRING {
    result = type_primitive("string")
    expr["type_info"] = result
    return result
  }

  # Arithmetic operators
  tc_unify(tc, left_type, right_type, expr["span"])
  expr["type_info"] = left_type
  return left_type
}

fn check_unary(tc: any, expr: any) -> any {
  operand_type = check_expr(tc, expr["operand"])
  op = expr["op"]

  if op == "!" {
    result = type_primitive("bool")
    expr["type_info"] = result
    return result
  }
  if op == "-" {
    expr["type_info"] = operand_type
    return operand_type
  }
  if op == "&" {
    result = type_ref(operand_type, expr["is_mut"] == true)
    expr["type_info"] = result
    return result
  }

  return operand_type
}

fn check_call(tc: any, expr: any) -> any {
  callee_type = check_expr(tc, expr["callee"])

  if callee_type != nil and callee_type["kind"] == TYPE_FN {
    # Check argument count
    if length(expr["args"]) != length(callee_type["param_types"]) {
      tc_error(tc, "Expected " + to_string(length(callee_type["param_types"])) +
               " arguments, got " + to_string(length(expr["args"])), expr["span"])
    } else {
      # Check each argument
      i = 0
      while i < length(expr["args"]) {
        arg_type = check_expr(tc, expr["args"][i])
        tc_unify(tc, callee_type["param_types"][i], arg_type, expr["span"])
        i = i + 1
      }
    }
    result = callee_type["return_type"]
    expr["type_info"] = result
    return result
  }

  # Unknown callee type
  i = 0
  while i < length(expr["args"]) {
    check_expr(tc, expr["args"][i])
    i = i + 1
  }
  return tc_fresh_type_var(tc)
}

fn check_method_call(tc: any, expr: any) -> any {
  object_type = check_expr(tc, expr["object"])
  i = 0
  while i < length(expr["args"]) {
    check_expr(tc, expr["args"][i])
    i = i + 1
  }
  return tc_fresh_type_var(tc)
}

fn check_field_access(tc: any, expr: any) -> any {
  object_type = check_expr(tc, expr["object"])
  object_type = tc_resolve(tc, object_type)

  if object_type != nil and object_type["kind"] == TYPE_STRUCT {
    i = 0
    while i < length(object_type["fields"]) {
      f = object_type["fields"][i]
      if f["name"] == expr["field"] {
        expr["type_info"] = f["type"]
        return f["type"]
      }
      i = i + 1
    }
    tc_error(tc, "No field '" + expr["field"] + "' on type " + object_type["name"], expr["span"])
  }

  return tc_fresh_type_var(tc)
}

fn check_index(tc: any, expr: any) -> any {
  object_type = check_expr(tc, expr["object"])
  index_type = check_expr(tc, expr["index"])

  object_type = tc_resolve(tc, object_type)

  if object_type != nil and object_type["kind"] == TYPE_ARRAY {
    expr["type_info"] = object_type["element_type"]
    return object_type["element_type"]
  }

  return tc_fresh_type_var(tc)
}

fn check_if_expr(tc: any, expr: any) -> any {
  cond_type = check_expr(tc, expr["condition"])
  tc_unify(tc, cond_type, type_primitive("bool"), expr["span"])

  then_type = check_block(tc, expr["then_block"])
  if expr["else_block"] != nil {
    else_type = nil
    if expr["else_block"]["kind"] == AST_IF_EXPR {
      else_type = check_expr(tc, expr["else_block"])
    } else {
      else_type = check_block(tc, expr["else_block"])
    }
    tc_unify(tc, then_type, else_type, expr["span"])
  }

  return then_type
}

fn check_match_expr(tc: any, expr: any) -> any {
  subject_type = check_expr(tc, expr["subject"])
  result_type = tc_fresh_type_var(tc)

  i = 0
  while i < length(expr["arms"]) {
    arm = expr["arms"][i]
    # Check pattern
    check_pattern(tc, arm["pattern"], subject_type)
    # Check guard
    if arm["guard"] != nil {
      guard_type = check_expr(tc, arm["guard"])
      tc_unify(tc, guard_type, type_primitive("bool"), expr["span"])
    }
    # Check body
    body_type = check_expr(tc, arm["body"])
    tc_unify(tc, result_type, body_type, expr["span"])
    i = i + 1
  }

  return result_type
}

fn check_array_literal(tc: any, expr: any) -> any {
  if length(expr["elements"]) == 0 {
    return type_array(tc_fresh_type_var(tc), nil)
  }

  elem_type = check_expr(tc, expr["elements"][0])
  i = 1
  while i < length(expr["elements"]) {
    et = check_expr(tc, expr["elements"][i])
    tc_unify(tc, elem_type, et, expr["span"])
    i = i + 1
  }

  return type_array(elem_type, length(expr["elements"]))
}

fn check_closure(tc: any, expr: any) -> any {
  tc_push_scope(tc)

  param_types = []
  i = 0
  while i < length(expr["params"]) {
    p = expr["params"][i]
    pt = nil
    if p["type_ann"] != nil {
      pt = resolve_type_annotation(tc, p["type_ann"])
    } else {
      pt = tc_fresh_type_var(tc)
    }
    tc_define(tc, p["name"], pt)
    push(param_types, pt)
    i = i + 1
  }

  body_type = check_expr(tc, expr["body"])
  tc_pop_scope(tc)

  return type_fn(param_types, body_type)
}

fn check_pattern(tc: any, pattern: any, expected_type: any) -> any {
  if pattern == nil {
    return nil
  }
  kind = pattern["kind"]

  match kind {
    AST_PAT_WILDCARD => { return nil },
    AST_PAT_IDENT => {
      tc_define(tc, pattern["name"], expected_type)
      return nil
    },
    AST_PAT_LITERAL => {
      return nil
    },
    _ => { return nil }
  }
}

# ---- Type Resolution from AST Annotations ----

fn resolve_type_annotation(tc: any, type_ast: any) -> any {
  if type_ast == nil {
    return tc_fresh_type_var(tc)
  }

  kind = type_ast["kind"]

  if kind == AST_TYPE_NAMED {
    name = type_ast["name"]
    # Check primitives
    primitive = tc_lookup(tc, name)
    if primitive != nil {
      return primitive
    }
    # Check user-defined types
    user_type = tc_lookup_type(tc, name)
    if user_type != nil {
      return user_type
    }
    return create_type(name)
  }

  if kind == AST_TYPE_GENERIC {
    type_args = []
    i = 0
    while i < length(type_ast["type_args"]) {
      push(type_args, resolve_type_annotation(tc, type_ast["type_args"][i]))
      i = i + 1
    }
    base = create_type(type_ast["name"])
    base["type_args"] = type_args
    return base
  }

  if kind == AST_TYPE_ARRAY {
    elem = resolve_type_annotation(tc, type_ast["element_type"])
    return type_array(elem, type_ast["size"])
  }

  if kind == AST_TYPE_FN {
    param_types = []
    i = 0
    while i < length(type_ast["param_types"]) {
      push(param_types, resolve_type_annotation(tc, type_ast["param_types"][i]))
      i = i + 1
    }
    ret = resolve_type_annotation(tc, type_ast["return_type"])
    return type_fn(param_types, ret)
  }

  if kind == AST_TYPE_REF {
    inner = resolve_type_annotation(tc, type_ast["inner_type"])
    return type_ref(inner, type_ast["is_mut"])
  }

  if kind == AST_TYPE_INFER {
    return tc_fresh_type_var(tc)
  }

  return tc_fresh_type_var(tc)
}

# ---- Type Display ----

fn type_to_string(t: any) -> string {
  if t == nil {
    return "unknown"
  }
  kind = t["kind"]

  if kind == TYPE_ARRAY {
    elem = type_to_string(t["element_type"])
    if t["array_size"] != nil {
      return "[" + elem + "; " + to_string(t["array_size"]) + "]"
    }
    return "[" + elem + "]"
  }
  if kind == TYPE_FN {
    params = ""
    i = 0
    while i < length(t["param_types"]) {
      if i > 0 { params = params + ", " }
      params = params + type_to_string(t["param_types"][i])
      i = i + 1
    }
    ret = type_to_string(t["return_type"])
    return "fn(" + params + ") -> " + ret
  }
  if kind == TYPE_REF {
    return "&" + type_to_string(t["inner_type"])
  }
  if kind == TYPE_MUT_REF {
    return "&mut " + type_to_string(t["inner_type"])
  }
  if kind == TYPE_OPTION {
    return "Option<" + type_to_string(t["inner_type"]) + ">"
  }
  if kind == TYPE_RESULT {
    return "Result<" + type_to_string(t["ok_type"]) + ", " + type_to_string(t["err_type"]) + ">"
  }
  if kind == TYPE_INFER {
    return "?T" + to_string(t["infer_id"])
  }

  return t["name"]
}

# ---- Type Checker Report ----

fn tc_report(tc: any) -> any {
  return {
    "checked_count": tc["checked_count"],
    "error_count": tc["error_count"],
    "warning_count": length(tc["warnings"]),
    "type_defs_count": length(tc["type_defs"]),
    "trait_defs_count": length(tc["trait_defs"]),
    "impl_count": length(tc["impl_defs"]),
    "infer_vars": tc["infer_counter"],
    "r3_pass": tc["error_count"] == 0  # R3: Type safety 100%
  }
}

// FreeLang Nano-Kernel: x86-64 Nano Bootloader
// Purpose: Ultra-minimal boot sequence for x86-64 bare metal
// R7: Boot time < 1 second, R8: Kernel size < 1 MB
// ~400 lines

module nano_bootloader

// ============================================================================
// Part 1: x86-64 Boot Configuration (60 lines)
// ============================================================================

enum BootArch {
    X86_64,
    Arm64,
    RiscV64,
}

enum BootMode {
    Bios,           // Legacy BIOS MBR boot
    Uefi,           // UEFI with GOP framebuffer
    Multiboot2,     // GRUB2 multiboot2
    LinuxHeader,    // Linux-compatible compressed kernel header
}

enum CpuMode {
    RealMode,       // 16-bit (startup)
    ProtectedMode,  // 32-bit (transient)
    LongMode,       // 64-bit (target)
}

struct NanoKernelConfig {
    arch: BootArch,
    mode: BootMode,
    entry_point: u64,
    stack_top: u64,
    kernel_base: u64,
    kernel_size_bytes: u64,
    heap_base: u64,
    heap_size_bytes: u64,
    uart_port: u32,
}

fn nano_default_config() -> NanoKernelConfig {
    return NanoKernelConfig {
        arch: BootArch::X86_64,
        mode: BootMode::Multiboot2,
        entry_point: 0x100000,      // 1MB — standard Linux load address
        stack_top: 0x1FF000,        // 2MB - 4KB for stack
        kernel_base: 0x100000,
        kernel_size_bytes: 524288,  // 512KB max (half of 1MB budget)
        heap_base: 0x200000,        // 2MB start for heap
        heap_size_bytes: 1048576,   // 1MB heap
        uart_port: 0x3F8,           // COM1
    }
}

// ============================================================================
// Part 2: CPU State Machine (80 lines)
// ============================================================================

struct X86CpuState {
    rip: u64,
    rsp: u64,
    rflags: u64,
    cr0: u64,       // Control Register 0 (PE, PG bits)
    cr3: u64,       // Page Directory Base
    cr4: u64,       // CR4 (PAE, PGE, etc.)
    efer: u64,      // Extended Feature Enable Register (LME = long mode enable)
    mode: CpuMode,
    core_id: u32,
    apic_id: u32,
}

impl X86CpuState {
    fn new_bsp() -> X86CpuState {
        return X86CpuState {
            rip: 0x7C00,        // MBR entry (BIOS) or 0x100000 (GRUB)
            rsp: 0x7C00,        // Stack below MBR
            rflags: 0x0002,     // reserved bit 1 always set
            cr0: 0x00000011,    // PE=1 (protected mode), ET=1
            cr3: 0,             // page table not set yet
            cr4: 0x00000020,    // PAE bit
            efer: 0x00000100,   // LME (Long Mode Enable)
            mode: CpuMode::RealMode,
            core_id: 0,
            apic_id: 0,
        }
    }

    fn enter_long_mode(&mut self) -> bool {
        if self.cr0 & 0x80000000 == 0 {
            return false    // PG not set — paging not enabled
        }
        if self.efer & 0x100 == 0 {
            return false    // LME not set
        }
        self.mode = CpuMode::LongMode
        self.rsp = 0x1FF000     // move stack to 2MB boundary
        return true
    }

    fn is_long_mode(&self) -> bool {
        return match self.mode {
            CpuMode::LongMode => true,
            _ => false,
        }
    }
}

// ============================================================================
// Part 3: Minimal Memory Map (70 lines)
// ============================================================================

enum MemoryRegionType {
    Free,
    KernelCode,
    KernelData,
    KernelStack,
    HeapRegion,
    Reserved,       // BIOS, ACPI, etc.
    BadMemory,
}

struct MemoryRegion {
    base: u64,
    size: u64,
    region_type: MemoryRegionType,
}

struct NanoMemoryMap {
    regions: array,         // MemoryRegion[]
    total_free_bytes: u64,
    total_bytes: u64,
}

fn build_memory_map(config: NanoKernelConfig) -> NanoMemoryMap {
    let regions = [
        MemoryRegion {
            base: 0x0000,
            size: 0x1000,           // 4KB
            region_type: MemoryRegionType::Reserved,    // IVT + BDA
        },
        MemoryRegion {
            base: 0x1000,
            size: 0x7C000,          // 496KB
            region_type: MemoryRegionType::Free,
        },
        MemoryRegion {
            base: 0x100000,
            size: config.kernel_size_bytes,
            region_type: MemoryRegionType::KernelCode,
        },
        MemoryRegion {
            base: config.stack_top - 65536,   // 64KB stack
            size: 65536,
            region_type: MemoryRegionType::KernelStack,
        },
        MemoryRegion {
            base: config.heap_base,
            size: config.heap_size_bytes,
            region_type: MemoryRegionType::HeapRegion,
        },
    ]

    return NanoMemoryMap {
        regions: regions,
        total_free_bytes: 524288 + config.heap_size_bytes,
        total_bytes: 16777216,  // 16MB assumed minimum
    }
}

// ============================================================================
// Part 4: GDT & IDT Minimal Setup (70 lines)
// ============================================================================

struct GdtEntry {
    base: u32,
    limit: u32,
    access: u8,     // Present, DPL, Type bits
    flags: u8,      // Granularity, 64-bit flag
}

struct NanoGdt {
    null_entry: GdtEntry,
    code64_entry: GdtEntry,
    data64_entry: GdtEntry,
    user_code64: GdtEntry,
    user_data64: GdtEntry,
}

fn build_nano_gdt() -> NanoGdt {
    return NanoGdt {
        null_entry: GdtEntry { base: 0, limit: 0, access: 0x00, flags: 0x00 },
        code64_entry: GdtEntry {
            base: 0, limit: 0xFFFFF,
            access: 0x9A,   // Present | Code | Execute | Read
            flags: 0xA,     // 64-bit | 4KB granularity
        },
        data64_entry: GdtEntry {
            base: 0, limit: 0xFFFFF,
            access: 0x92,   // Present | Data | Read | Write
            flags: 0xC,
        },
        user_code64: GdtEntry {
            base: 0, limit: 0xFFFFF,
            access: 0xFA,   // Present | DPL3 | Code
            flags: 0xA,
        },
        user_data64: GdtEntry {
            base: 0, limit: 0xFFFFF,
            access: 0xF2,   // Present | DPL3 | Data
            flags: 0xC,
        },
    }
}

// ============================================================================
// Part 5: Boot Sequence Phases (80 lines)
// ============================================================================

enum BootPhase {
    PowerOn,            // CPU reset, A20 line gate
    MemoryDetect,       // BIOS INT 0x15 / UEFI GetMemoryMap
    ModeSwitch,         // real → protected → long mode
    KernelLoad,         // load kernel from disk/UEFI volume
    DriverInit,         // initialize UART, framebuffer, APIC
    KernelEntry,        // jump to kernel main
    KernelRunning,      // running
    Halt,               // HLT loop
}

struct BootState {
    phase: BootPhase,
    elapsed_ms: u32,
    errors: array,      // string[]
    cpu: X86CpuState,
    memory_map: NanoMemoryMap,
}

fn init_boot_state(config: NanoKernelConfig) -> BootState {
    return BootState {
        phase: BootPhase::PowerOn,
        elapsed_ms: 0,
        errors: [],
        cpu: X86CpuState::new_bsp(),
        memory_map: build_memory_map(config),
    }
}

fn advance_phase(state: BootState) -> BootState {
    let next_phase = match state.phase {
        BootPhase::PowerOn     => BootPhase::MemoryDetect,
        BootPhase::MemoryDetect => BootPhase::ModeSwitch,
        BootPhase::ModeSwitch  => BootPhase::KernelLoad,
        BootPhase::KernelLoad  => BootPhase::DriverInit,
        BootPhase::DriverInit  => BootPhase::KernelEntry,
        BootPhase::KernelEntry => BootPhase::KernelRunning,
        BootPhase::KernelRunning => BootPhase::KernelRunning,
        BootPhase::Halt         => BootPhase::Halt,
    }
    return BootState {
        phase: next_phase,
        elapsed_ms: state.elapsed_ms + 50,  // simulate 50ms per phase
        errors: state.errors,
        cpu: state.cpu,
        memory_map: state.memory_map,
    }
}

// ============================================================================
// Part 6: UART Serial Output (40 lines)
// ============================================================================

struct NanoUart {
    port: u32,
    baud: u32,
    initialized: bool,
}

impl NanoUart {
    fn new(port: u32) -> NanoUart {
        return NanoUart {
            port: port,
            baud: 115200,
            initialized: false,
        }
    }

    fn init(&mut self) -> bool {
        // Simulate UART init: set baud rate, 8N1
        // Real: outb(port+3, 0x80); outb(port, 0x01); outb(port+1, 0); outb(port+3, 0x03)
        self.initialized = true
        return true
    }

    fn write_str(&self, s: string) -> bool {
        if !self.initialized {
            return false
        }
        // Real: loop each char, poll THRE bit in LSR (port+5)
        return true
    }
}

// ============================================================================
// Part 7: Boot Validation (R7 + R8) (80 lines)
// ============================================================================

struct BootMetrics {
    total_boot_time_ms: u32,
    kernel_binary_size_bytes: u64,
    memory_map_entries: u32,
    gdt_entries: u32,
    uart_ready: bool,
    long_mode_active: bool,
    phases_completed: u32,
}

impl BootMetrics {
    fn r7_pass(&self) -> bool {
        // R7: Boot time < 1 second = 1000ms
        return self.total_boot_time_ms < 1000
    }

    fn r8_pass(&self) -> bool {
        // R8: Kernel binary < 1MB = 1,048,576 bytes
        return self.kernel_binary_size_bytes < 1048576
    }

    fn summary(&self) -> string {
        let r7 = if self.r7_pass() { "PASS" } else { "FAIL" }
        let r8 = if self.r8_pass() { "PASS" } else { "FAIL" }
        return "BootMetrics: boot_time=" + string(self.total_boot_time_ms) + "ms R7=" + r7
               + " kernel_size=" + string(self.kernel_binary_size_bytes) + "B R8=" + r8
    }
}

fn run_nano_boot(config: NanoKernelConfig) -> BootMetrics {
    let mut state = init_boot_state(config)
    let mut uart = NanoUart::new(config.uart_port)
    uart.init()
    uart.write_str("[NANO] Boot start\n")

    let mut phases_done = 0

    // Execute boot phases
    let mut i = 0
    while i < 6 {
        state = advance_phase(state)
        phases_done = phases_done + 1
        i = i + 1
    }

    // Enter long mode
    let mut cpu = X86CpuState::new_bsp()
    cpu.cr0 = 0x80000011   // PG+PE
    cpu.efer = 0x00000100  // LME
    let lm_ok = cpu.enter_long_mode()

    uart.write_str("[NANO] Long mode: " + if lm_ok { "YES" } else { "NO" } + "\n")

    return BootMetrics {
        total_boot_time_ms: state.elapsed_ms,
        kernel_binary_size_bytes: config.kernel_size_bytes,
        memory_map_entries: 5,
        gdt_entries: 5,
        uart_ready: uart.initialized,
        long_mode_active: lm_ok,
        phases_completed: phases_done,
    }
}

// ============================================================================
// Part 8: Public API (20 lines)
// ============================================================================

fn nano_boot() -> BootMetrics {
    let config = nano_default_config()
    return run_nano_boot(config)
}

fn nano_boot_custom(kernel_size_bytes: u64) -> BootMetrics {
    let mut config = nano_default_config()
    config.kernel_size_bytes = kernel_size_bytes
    return run_nano_boot(config)
}

# ================================================================
# FreeLang v4 Core - Intermediate Representation (IR)
# Three-address code with SSA form for optimization
# ================================================================

# ---- IR Opcode Constants ----

# Arithmetic
IR_ADD      = "ADD"
IR_SUB      = "SUB"
IR_MUL      = "MUL"
IR_DIV      = "DIV"
IR_MOD      = "MOD"
IR_NEG      = "NEG"
IR_POW      = "POW"

# Bitwise
IR_BAND     = "BAND"
IR_BOR      = "BOR"
IR_BXOR     = "BXOR"
IR_BNOT     = "BNOT"
IR_SHL      = "SHL"
IR_SHR      = "SHR"

# Comparison
IR_EQ       = "EQ"
IR_NEQ      = "NEQ"
IR_LT       = "LT"
IR_GT       = "GT"
IR_LTE      = "LTE"
IR_GTE      = "GTE"

# Logical
IR_AND      = "AND"
IR_OR       = "OR"
IR_NOT      = "NOT"

# Control flow
IR_JMP      = "JMP"
IR_JMP_IF   = "JMP_IF"
IR_JMP_NIF  = "JMP_NIF"
IR_CALL     = "CALL"
IR_RET      = "RET"
IR_NOP      = "NOP"
IR_HALT     = "HALT"

# Memory
IR_LOAD     = "LOAD"
IR_STORE    = "STORE"
IR_ALLOC    = "ALLOC"
IR_FREE     = "FREE"
IR_LOAD_FIELD   = "LOAD_FIELD"
IR_STORE_FIELD  = "STORE_FIELD"
IR_LOAD_INDEX   = "LOAD_INDEX"
IR_STORE_INDEX  = "STORE_INDEX"

# Constants
IR_CONST_INT    = "CONST_INT"
IR_CONST_FLOAT  = "CONST_FLOAT"
IR_CONST_STR    = "CONST_STR"
IR_CONST_BOOL   = "CONST_BOOL"
IR_CONST_NIL    = "CONST_NIL"

# SSA
IR_PHI      = "PHI"
IR_MOVE     = "MOVE"
IR_CAST     = "CAST"

# Object operations
IR_NEW_ARRAY    = "NEW_ARRAY"
IR_NEW_STRUCT   = "NEW_STRUCT"
IR_NEW_CLOSURE  = "NEW_CLOSURE"

# ---- IR Instruction ----

fn ir_instr(op: string, dest: any, src1: any, src2: any) -> any {
  return {
    "op": op,
    "dest": dest,
    "src1": src1,
    "src2": src2,
    "label": nil,
    "block_id": 0,
    "line": 0,
    "comment": ""
  }
}

fn ir_const(dest: any, op: string, value: any) -> any {
  instr = ir_instr(op, dest, value, nil)
  return instr
}

fn ir_jump(target_label: string) -> any {
  instr = ir_instr(IR_JMP, nil, nil, nil)
  instr["label"] = target_label
  return instr
}

fn ir_jump_if(condition: any, target_label: string) -> any {
  instr = ir_instr(IR_JMP_IF, nil, condition, nil)
  instr["label"] = target_label
  return instr
}

fn ir_jump_nif(condition: any, target_label: string) -> any {
  instr = ir_instr(IR_JMP_NIF, nil, condition, nil)
  instr["label"] = target_label
  return instr
}

fn ir_call(dest: any, func: any, args: array) -> any {
  instr = ir_instr(IR_CALL, dest, func, nil)
  instr["args"] = args
  return instr
}

fn ir_ret(value: any) -> any {
  return ir_instr(IR_RET, nil, value, nil)
}

fn ir_phi(dest: any, sources: array) -> any {
  instr = ir_instr(IR_PHI, dest, nil, nil)
  instr["sources"] = sources  # [{value, block_id}, ...]
  return instr
}

# ---- Basic Block ----

fn ir_basic_block(id: i32, label: string) -> any {
  return {
    "id": id,
    "label": label,
    "instructions": [],
    "predecessors": [],
    "successors": [],
    "dominators": [],
    "phi_nodes": [],
    "is_entry": false,
    "is_exit": false,
    "loop_header": false,
    "loop_depth": 0
  }
}

fn bb_add_instr(bb: any, instr: any) -> any {
  instr["block_id"] = bb["id"]
  push(bb["instructions"], instr)
  return bb
}

fn bb_add_predecessor(bb: any, pred_id: i32) -> any {
  push(bb["predecessors"], pred_id)
  return bb
}

fn bb_add_successor(bb: any, succ_id: i32) -> any {
  push(bb["successors"], succ_id)
  return bb
}

fn bb_is_terminated(bb: any) -> bool {
  instrs = bb["instructions"]
  if length(instrs) == 0 {
    return false
  }
  last = instrs[length(instrs) - 1]
  return last["op"] == IR_JMP or last["op"] == IR_JMP_IF or
         last["op"] == IR_JMP_NIF or last["op"] == IR_RET or
         last["op"] == IR_HALT
}

# ---- IR Function ----

fn ir_function(name: string, params: array, return_type: any) -> any {
  entry_block = ir_basic_block(0, name + "_entry")
  entry_block["is_entry"] = true

  return {
    "name": name,
    "params": params,
    "return_type": return_type,
    "blocks": [entry_block],
    "block_count": 1,
    "register_count": 0,
    "local_count": 0,
    "constants": [],
    "labels": {},
    "is_entry_point": false
  }
}

fn ir_func_new_block(func: any, label: string) -> any {
  id = func["block_count"]
  func["block_count"] = id + 1
  bb = ir_basic_block(id, label)
  push(func["blocks"], bb)
  return bb
}

fn ir_func_new_register(func: any) -> string {
  id = func["register_count"]
  func["register_count"] = id + 1
  return "%r" + to_string(id)
}

fn ir_func_new_local(func: any, name: string) -> string {
  func["local_count"] = func["local_count"] + 1
  return "%" + name
}

fn ir_func_add_constant(func: any, value: any) -> i32 {
  idx = length(func["constants"])
  push(func["constants"], value)
  return idx
}

fn ir_func_get_block(func: any, id: i32) -> any {
  if id >= 0 and id < length(func["blocks"]) {
    return func["blocks"][id]
  }
  return nil
}

# ---- IR Module ----

fn ir_module(name: string) -> any {
  return {
    "name": name,
    "functions": [],
    "globals": [],
    "type_defs": [],
    "string_pool": [],
    "entry_function": nil
  }
}

fn ir_module_add_function(mod: any, func: any) -> any {
  push(mod["functions"], func)
  if func["is_entry_point"] {
    mod["entry_function"] = func["name"]
  }
  return mod
}

fn ir_module_add_global(mod: any, name: string, type_info: any, value: any) -> any {
  push(mod["globals"], { "name": name, "type": type_info, "value": value })
  return mod
}

fn ir_module_intern_string(mod: any, s: string) -> i32 {
  # Check if already interned
  i = 0
  while i < length(mod["string_pool"]) {
    if mod["string_pool"][i] == s {
      return i
    }
    i = i + 1
  }
  idx = length(mod["string_pool"])
  push(mod["string_pool"], s)
  return idx
}

# ---- IR Pretty Printer ----

fn ir_instr_to_string(instr: any) -> string {
  op = instr["op"]
  result = ""

  if instr["dest"] != nil {
    result = result + instr["dest"] + " = "
  }

  result = result + op

  if instr["src1"] != nil {
    result = result + " " + to_string(instr["src1"])
  }
  if instr["src2"] != nil {
    result = result + ", " + to_string(instr["src2"])
  }
  if instr["label"] != nil {
    result = result + " @" + instr["label"]
  }
  if instr["args"] != nil {
    result = result + "("
    i = 0
    while i < length(instr["args"]) {
      if i > 0 { result = result + ", " }
      result = result + to_string(instr["args"][i])
      i = i + 1
    }
    result = result + ")"
  }
  if instr["comment"] != "" {
    result = result + "  # " + instr["comment"]
  }

  return result
}

fn ir_block_to_string(bb: any) -> string {
  result = bb["label"] + ":"
  if bb["is_entry"] { result = result + " (entry)" }
  if bb["is_exit"] { result = result + " (exit)" }
  result = result + "\n"

  i = 0
  while i < length(bb["instructions"]) {
    result = result + "  " + ir_instr_to_string(bb["instructions"][i]) + "\n"
    i = i + 1
  }

  return result
}

fn ir_function_to_string(func: any) -> string {
  result = "fn " + func["name"] + "("
  i = 0
  while i < length(func["params"]) {
    if i > 0 { result = result + ", " }
    result = result + func["params"][i]
    i = i + 1
  }
  result = result + ")"
  if func["return_type"] != nil {
    result = result + " -> " + to_string(func["return_type"])
  }
  result = result + " {\n"

  i = 0
  while i < length(func["blocks"]) {
    result = result + ir_block_to_string(func["blocks"][i])
    i = i + 1
  }

  result = result + "}\n"
  return result
}

fn ir_module_to_string(mod: any) -> string {
  result = "# IR Module: " + mod["name"] + "\n\n"

  # Globals
  i = 0
  while i < length(mod["globals"]) {
    g = mod["globals"][i]
    result = result + "global " + g["name"] + " = " + to_string(g["value"]) + "\n"
    i = i + 1
  }
  if length(mod["globals"]) > 0 {
    result = result + "\n"
  }

  # Functions
  i = 0
  while i < length(mod["functions"]) {
    result = result + ir_function_to_string(mod["functions"][i]) + "\n"
    i = i + 1
  }

  return result
}

# ---- IR Statistics ----

fn ir_module_stats(mod: any) -> any {
  total_blocks = 0
  total_instrs = 0
  total_functions = length(mod["functions"])

  i = 0
  while i < total_functions {
    func = mod["functions"][i]
    total_blocks = total_blocks + length(func["blocks"])
    j = 0
    while j < length(func["blocks"]) {
      total_instrs = total_instrs + length(func["blocks"][j]["instructions"])
      j = j + 1
    }
    i = i + 1
  }

  return {
    "functions": total_functions,
    "blocks": total_blocks,
    "instructions": total_instrs,
    "globals": length(mod["globals"]),
    "strings": length(mod["string_pool"])
  }
}

// FreeLang JIT Compiler: Skeleton
// Purpose: Tracing JIT compiler for FreeLang bytecode
// Target: x86-64 machine code emission
// ~300 lines

module jit_compiler

// ============================================================================
// Part 1: JIT Overview and Core Types (50 lines)
// ============================================================================

// JIT Strategy: Tracing JIT
// 1. Interpret bytecode normally
// 2. Profile hot loops (trace threshold = 100 executions)
// 3. Record trace of hot loop
// 4. Compile trace to x86-64 native code
// 5. Execute native code on next iteration

enum JitState {
    Interpreting,       // normal bytecode interpretation
    Profiling,          // recording execution counts
    Tracing,            // recording trace of hot loop
    Compiling,          // compiling trace to native
    Executing,          // running native code
    Deoptimizing,       // fallback to interpreter (guard failed)
}

enum BytecodeOp {
    LoadInt(i64),
    LoadFloat(f64),
    LoadLocal(u32),
    StoreLocal(u32),
    Add,
    Sub,
    Mul,
    Div,
    Cmp(CmpOp),
    Jump(i32),          // relative offset
    JumpIfTrue(i32),
    JumpIfFalse(i32),
    Call(u32),          // function id
    Return,
    Nop,
}

enum CmpOp {
    Lt, Le, Eq, Ne, Ge, Gt,
}

struct JitConfig {
    trace_threshold: u32,       // hot loop threshold
    max_trace_length: u32,      // max bytecodes in one trace
    code_cache_size_bytes: u64,
    enable_inlining: bool,
    enable_type_specialization: bool,
    debug_mode: bool,
}

fn jit_default_config() -> JitConfig {
    return JitConfig {
        trace_threshold: 100,
        max_trace_length: 1000,
        code_cache_size_bytes: 16777216,    // 16MB code cache
        enable_inlining: true,
        enable_type_specialization: true,
        debug_mode: false,
    }
}

// ============================================================================
// Part 2: Profiler (60 lines)
// ============================================================================

struct ExecutionCounter {
    pc: u64,            // bytecode program counter
    count: u64,
    is_loop_header: bool,
}

struct JitProfiler {
    counters: array,        // ExecutionCounter[]
    hot_loops: array,       // u64[] - PCs of hot loops
    trace_threshold: u32,
}

impl JitProfiler {
    fn new(threshold: u32) -> JitProfiler {
        return JitProfiler {
            counters: [],
            hot_loops: [],
            trace_threshold: threshold,
        }
    }

    fn record_execution(&mut self, pc: u64) -> bool {
        // Find or create counter for this PC
        let mut i = 0
        while i < length(self.counters) {
            let counter = self.counters[i]
            if counter.pc == pc {
                counter.count = counter.count + 1
                // Check if hot
                if counter.count >= u64(self.trace_threshold) && counter.is_loop_header {
                    push(self.hot_loops, pc)
                    return true     // signal: start tracing
                }
                return false
            }
            i = i + 1
        }
        // New counter
        push(self.counters, ExecutionCounter {
            pc: pc,
            count: 1,
            is_loop_header: false,
        })
        return false
    }

    fn mark_loop_header(&mut self, pc: u64) {
        let mut i = 0
        while i < length(self.counters) {
            if self.counters[i].pc == pc {
                self.counters[i].is_loop_header = true
                return
            }
            i = i + 1
        }
        push(self.counters, ExecutionCounter {
            pc: pc,
            count: 0,
            is_loop_header: true,
        })
    }

    fn is_hot(&self, pc: u64) -> bool {
        let mut i = 0
        while i < length(self.hot_loops) {
            if self.hot_loops[i] == pc {
                return true
            }
            i = i + 1
        }
        return false
    }
}

// ============================================================================
// Part 3: Trace Recorder (60 lines)
// ============================================================================

struct TraceInstruction {
    op: string,             // simplified instruction representation
    operands: array,        // mixed operands
    type_guard: string,     // expected type (for type specialization)
}

struct Trace {
    id: u64,
    start_pc: u64,
    instructions: array,    // TraceInstruction[]
    exit_guards: array,     // guard conditions for fallback
    call_count: u64,        // how many times this trace executed natively
    compiled_addr: u64,     // address of compiled native code (0 = not compiled)
}

struct TraceRecorder {
    current_trace: Trace,
    is_recording: bool,
    max_length: u32,
    next_trace_id: u64,
}

impl TraceRecorder {
    fn new(max_len: u32) -> TraceRecorder {
        return TraceRecorder {
            current_trace: Trace {
                id: 0,
                start_pc: 0,
                instructions: [],
                exit_guards: [],
                call_count: 0,
                compiled_addr: 0,
            },
            is_recording: false,
            max_length: max_len,
            next_trace_id: 0,
        }
    }

    fn start_trace(&mut self, pc: u64) {
        self.is_recording = true
        self.next_trace_id = self.next_trace_id + 1
        self.current_trace = Trace {
            id: self.next_trace_id,
            start_pc: pc,
            instructions: [],
            exit_guards: [],
            call_count: 0,
            compiled_addr: 0,
        }
    }

    fn record_op(&mut self, op: string, type_guard: string) -> bool {
        if !self.is_recording {
            return false
        }
        if length(self.current_trace.instructions) >= u32(self.max_length) {
            self.is_recording = false
            return false    // trace too long
        }
        push(self.current_trace.instructions, TraceInstruction {
            op: op,
            operands: [],
            type_guard: type_guard,
        })
        return true
    }

    fn finish_trace(&mut self) -> Trace {
        self.is_recording = false
        return self.current_trace
    }
}

// ============================================================================
// Part 4: Code Cache (60 lines)
// ============================================================================

struct CodeRegion {
    trace_id: u64,
    base_addr: u64,
    size_bytes: u32,
    hot_count: u64,
    eviction_score: f64,
}

struct CodeCache {
    regions: array,         // CodeRegion[]
    total_bytes: u64,
    used_bytes: u64,
    next_addr: u64,
    evictions: u64,
}

impl CodeCache {
    fn new(size_bytes: u64) -> CodeCache {
        return CodeCache {
            regions: [],
            total_bytes: size_bytes,
            used_bytes: 0,
            next_addr: 0x70000000,  // simulated JIT code region start
            evictions: 0,
        }
    }

    fn allocate(&mut self, trace_id: u64, size_bytes: u32) -> u64 {
        if u64(size_bytes) + self.used_bytes > self.total_bytes {
            // Evict oldest/coldest region
            self.evict_one()
        }
        let addr = self.next_addr
        self.next_addr = self.next_addr + u64(size_bytes)
        self.used_bytes = self.used_bytes + u64(size_bytes)
        push(self.regions, CodeRegion {
            trace_id: trace_id,
            base_addr: addr,
            size_bytes: size_bytes,
            hot_count: 0,
            eviction_score: 0.0,
        })
        return addr
    }

    fn evict_one(&mut self) {
        if length(self.regions) == 0 {
            return
        }
        // Evict region with lowest hot_count (LRU approximation)
        let mut min_i = 0
        let mut min_hot = self.regions[0].hot_count
        let mut i = 1
        while i < length(self.regions) {
            if self.regions[i].hot_count < min_hot {
                min_hot = self.regions[i].hot_count
                min_i = i
            }
            i = i + 1
        }
        let evicted = self.regions[min_i]
        self.used_bytes = self.used_bytes - u64(evicted.size_bytes)
        self.evictions = self.evictions + 1
        // Remove from array (simplified: mark as 0)
        self.regions[min_i].size_bytes = 0
    }

    fn utilization(&self) -> f64 {
        if self.total_bytes == 0 { return 0.0 }
        return f64(self.used_bytes) / f64(self.total_bytes)
    }
}

// ============================================================================
// Part 5: JIT Compiler Facade (70 lines)
// ============================================================================

struct JitCompiler {
    config: JitConfig,
    profiler: JitProfiler,
    recorder: TraceRecorder,
    code_cache: CodeCache,
    state: JitState,
    compiled_traces: u64,
    deoptimizations: u64,
    total_native_executions: u64,
}

impl JitCompiler {
    fn new() -> JitCompiler {
        let cfg = jit_default_config()
        return JitCompiler {
            config: cfg,
            profiler: JitProfiler::new(cfg.trace_threshold),
            recorder: TraceRecorder::new(cfg.max_trace_length),
            code_cache: CodeCache::new(cfg.code_cache_size_bytes),
            state: JitState::Interpreting,
            compiled_traces: 0,
            deoptimizations: 0,
            total_native_executions: 0,
        }
    }

    fn on_bytecode_execute(&mut self, pc: u64, op_name: string) -> bool {
        // Returns true if we should switch to native execution
        match self.state {
            JitState::Interpreting => {
                let is_hot = self.profiler.record_execution(pc)
                if is_hot {
                    self.state = JitState::Tracing
                    self.recorder.start_trace(pc)
                }
                return false
            },
            JitState::Tracing => {
                self.recorder.record_op(op_name, "any")
                return false
            },
            JitState::Executing => {
                self.total_native_executions = self.total_native_executions + 1
                return true
            },
            _ => return false,
        }
    }

    fn compile_current_trace(&mut self) -> u64 {
        // Finish recording and compile
        let trace = self.recorder.finish_trace()
        let estimated_size = u32(length(trace.instructions)) * 6  // ~6 bytes/instruction
        let addr = self.code_cache.allocate(trace.id, estimated_size)

        if addr > 0 {
            self.compiled_traces = self.compiled_traces + 1
            self.state = JitState::Executing
        } else {
            self.state = JitState::Interpreting
        }
        return addr
    }

    fn deoptimize(&mut self, reason: string) {
        self.deoptimizations = self.deoptimizations + 1
        self.state = JitState::Interpreting
    }

    fn metrics_summary(&self) -> string {
        return "JIT: compiled_traces=" + string(self.compiled_traces)
               + " deopt=" + string(self.deoptimizations)
               + " native_exec=" + string(self.total_native_executions)
               + " cache_util=" + string(self.code_cache.utilization())
    }
}

