# ================================================================
# FreeLang v4 Example: Expression Calculator
# Tokenizer + Recursive Descent Parser + Evaluator
# Demonstrates the complete interpreter pattern
# ================================================================

# ---- Token Types ----

CALC_NUMBER   = "number"
CALC_PLUS     = "plus"
CALC_MINUS    = "minus"
CALC_STAR     = "star"
CALC_SLASH    = "slash"
CALC_PERCENT  = "percent"
CALC_POWER    = "power"
CALC_LPAREN   = "lparen"
CALC_RPAREN   = "rparen"
CALC_IDENT    = "ident"
CALC_ASSIGN   = "assign"
CALC_COMMA    = "comma"
CALC_EOF      = "eof"
CALC_ERROR    = "error"

# ---- Tokenizer ----

fn calc_tokenize(input: string) -> array {
  tokens = []
  i = 0
  len = length(input)

  while i < len {
    ch = char_at(input, i)

    # Skip whitespace
    if ch == " " or ch == "\t" or ch == "\n" {
      i = i + 1
      continue
    }

    # Numbers (integers and floats)
    if (ch >= "0" and ch <= "9") or ch == "." {
      start = i
      has_dot = false
      while i < len {
        c = char_at(input, i)
        if c == "." and not has_dot {
          has_dot = true
          i = i + 1
        } else if c >= "0" and c <= "9" {
          i = i + 1
        } else {
          break
        }
      }
      num_str = substring(input, start, i)
      push(tokens, { "type": CALC_NUMBER, "value": parse_number(num_str) })
      continue
    }

    # Identifiers (function names, variables)
    if (ch >= "a" and ch <= "z") or (ch >= "A" and ch <= "Z") or ch == "_" {
      start = i
      while i < len {
        c = char_at(input, i)
        if (c >= "a" and c <= "z") or (c >= "A" and c <= "Z") or
           (c >= "0" and c <= "9") or c == "_" {
          i = i + 1
        } else {
          break
        }
      }
      push(tokens, { "type": CALC_IDENT, "value": substring(input, start, i) })
      continue
    }

    # Operators
    if ch == "+" { push(tokens, { "type": CALC_PLUS }); i = i + 1; continue }
    if ch == "-" { push(tokens, { "type": CALC_MINUS }); i = i + 1; continue }
    if ch == "*" {
      if i + 1 < len and char_at(input, i + 1) == "*" {
        push(tokens, { "type": CALC_POWER })
        i = i + 2
      } else {
        push(tokens, { "type": CALC_STAR })
        i = i + 1
      }
      continue
    }
    if ch == "/" { push(tokens, { "type": CALC_SLASH }); i = i + 1; continue }
    if ch == "%" { push(tokens, { "type": CALC_PERCENT }); i = i + 1; continue }
    if ch == "^" { push(tokens, { "type": CALC_POWER }); i = i + 1; continue }
    if ch == "(" { push(tokens, { "type": CALC_LPAREN }); i = i + 1; continue }
    if ch == ")" { push(tokens, { "type": CALC_RPAREN }); i = i + 1; continue }
    if ch == "=" { push(tokens, { "type": CALC_ASSIGN }); i = i + 1; continue }
    if ch == "," { push(tokens, { "type": CALC_COMMA }); i = i + 1; continue }

    # Unknown character
    push(tokens, { "type": CALC_ERROR, "value": ch })
    i = i + 1
  }

  push(tokens, { "type": CALC_EOF })
  return tokens
}

# ---- Parser State ----

fn calc_parser_create(tokens: array) -> any {
  return {
    "tokens": tokens,
    "pos": 0,
    "variables": {},
    "functions": {}
  }
}

fn calc_current(parser: any) -> any {
  if parser["pos"] >= length(parser["tokens"]) {
    return { "type": CALC_EOF }
  }
  return parser["tokens"][parser["pos"]]
}

fn calc_advance(parser: any) -> any {
  token = calc_current(parser)
  parser["pos"] = parser["pos"] + 1
  return token
}

fn calc_expect(parser: any, token_type: string) -> any {
  token = calc_advance(parser)
  if token["type"] != token_type {
    return nil
  }
  return token
}

# ---- Parser (Recursive Descent) ----

fn calc_parse_expression(parser: any) -> f64 {
  # Check for variable assignment: ident = expr
  if calc_current(parser)["type"] == CALC_IDENT {
    saved_pos = parser["pos"]
    name = calc_advance(parser)["value"]
    if calc_current(parser)["type"] == CALC_ASSIGN {
      calc_advance(parser)
      value = calc_parse_additive(parser)
      parser["variables"][name] = value
      return value
    }
    # Not assignment, backtrack
    parser["pos"] = saved_pos
  }

  return calc_parse_additive(parser)
}

fn calc_parse_additive(parser: any) -> f64 {
  left = calc_parse_multiplicative(parser)

  while true {
    t = calc_current(parser)["type"]
    if t == CALC_PLUS {
      calc_advance(parser)
      right = calc_parse_multiplicative(parser)
      left = left + right
    } else if t == CALC_MINUS {
      calc_advance(parser)
      right = calc_parse_multiplicative(parser)
      left = left - right
    } else {
      break
    }
  }

  return left
}

fn calc_parse_multiplicative(parser: any) -> f64 {
  left = calc_parse_power(parser)

  while true {
    t = calc_current(parser)["type"]
    if t == CALC_STAR {
      calc_advance(parser)
      right = calc_parse_power(parser)
      left = left * right
    } else if t == CALC_SLASH {
      calc_advance(parser)
      right = calc_parse_power(parser)
      if right == 0 {
        println("Error: Division by zero")
        return 0
      }
      left = left / right
    } else if t == CALC_PERCENT {
      calc_advance(parser)
      right = calc_parse_power(parser)
      if right == 0 {
        println("Error: Modulo by zero")
        return 0
      }
      left = left % right
    } else {
      break
    }
  }

  return left
}

fn calc_parse_power(parser: any) -> f64 {
  base = calc_parse_unary(parser)

  if calc_current(parser)["type"] == CALC_POWER {
    calc_advance(parser)
    exp = calc_parse_power(parser)  # Right-associative
    return pow(base, exp)
  }

  return base
}

fn calc_parse_unary(parser: any) -> f64 {
  if calc_current(parser)["type"] == CALC_MINUS {
    calc_advance(parser)
    return -calc_parse_unary(parser)
  }
  if calc_current(parser)["type"] == CALC_PLUS {
    calc_advance(parser)
    return calc_parse_unary(parser)
  }
  return calc_parse_primary(parser)
}

fn calc_parse_primary(parser: any) -> f64 {
  token = calc_current(parser)

  # Number literal
  if token["type"] == CALC_NUMBER {
    calc_advance(parser)
    return token["value"]
  }

  # Parenthesized expression
  if token["type"] == CALC_LPAREN {
    calc_advance(parser)
    value = calc_parse_expression(parser)
    calc_expect(parser, CALC_RPAREN)
    return value
  }

  # Identifier (variable or function call)
  if token["type"] == CALC_IDENT {
    name = calc_advance(parser)["value"]

    # Function call
    if calc_current(parser)["type"] == CALC_LPAREN {
      calc_advance(parser)
      args = []

      if calc_current(parser)["type"] != CALC_RPAREN {
        push(args, calc_parse_expression(parser))
        while calc_current(parser)["type"] == CALC_COMMA {
          calc_advance(parser)
          push(args, calc_parse_expression(parser))
        }
      }
      calc_expect(parser, CALC_RPAREN)

      return calc_call_function(parser, name, args)
    }

    # Variable lookup
    if parser["variables"][name] != nil {
      return parser["variables"][name]
    }

    # Constants
    if name == "pi" or name == "PI" { return 3.141592653589793 }
    if name == "e" or name == "E" { return 2.718281828459045 }
    if name == "tau" or name == "TAU" { return 6.283185307179586 }

    println("Error: Unknown variable '" + name + "'")
    return 0
  }

  println("Error: Unexpected token")
  calc_advance(parser)
  return 0
}

# ---- Built-in Functions ----

fn calc_call_function(parser: any, name: string, args: array) -> f64 {
  n = length(args)

  # Math functions (1 argument)
  if n == 1 {
    x = args[0]
    if name == "abs" { return if x < 0 { -x } else { x } }
    if name == "sqrt" { return pow(x, 0.5) }
    if name == "cbrt" { return pow(x, 1.0 / 3.0) }
    if name == "floor" { return floor(x) }
    if name == "ceil" { return ceil(x) }
    if name == "round" { return round(x) }
    if name == "sin" { return sin(x) }
    if name == "cos" { return cos(x) }
    if name == "tan" { return tan(x) }
    if name == "asin" { return asin(x) }
    if name == "acos" { return acos(x) }
    if name == "atan" { return atan(x) }
    if name == "exp" { return exp(x) }
    if name == "ln" or name == "log" { return ln(x) }
    if name == "log2" { return log2(x) }
    if name == "log10" { return log10(x) }
    if name == "deg" { return x * 180.0 / 3.141592653589793 }
    if name == "rad" { return x * 3.141592653589793 / 180.0 }
    if name == "sign" { return if x > 0 { 1 } else if x < 0 { -1 } else { 0 } }
    if name == "fact" or name == "factorial" {
      result = 1
      i = 2
      while i <= x {
        result = result * i
        i = i + 1
      }
      return result
    }
  }

  # Math functions (2 arguments)
  if n == 2 {
    if name == "pow" or name == "power" { return pow(args[0], args[1]) }
    if name == "max" { return if args[0] > args[1] { args[0] } else { args[1] } }
    if name == "min" { return if args[0] < args[1] { args[0] } else { args[1] } }
    if name == "mod" { return args[0] % args[1] }
    if name == "atan2" { return atan2(args[0], args[1]) }
    if name == "hypot" { return pow(args[0] * args[0] + args[1] * args[1], 0.5) }
    if name == "gcd" {
      a = args[0]
      b = args[1]
      while b != 0 {
        temp = b
        b = a % b
        a = temp
      }
      return a
    }
    if name == "lcm" {
      a = args[0]
      b = args[1]
      g = a
      t = b
      while t != 0 {
        temp = t
        t = g % t
        g = temp
      }
      return (a * b) / g
    }
  }

  # Clamp (3 arguments)
  if n == 3 and name == "clamp" {
    val = args[0]
    lo = args[1]
    hi = args[2]
    if val < lo { return lo }
    if val > hi { return hi }
    return val
  }

  println("Error: Unknown function '" + name + "' with " + to_string(n) + " arguments")
  return 0
}

# ---- Calculator REPL ----

fn calc_evaluate(expr: string) -> f64 {
  tokens = calc_tokenize(expr)
  parser = calc_parser_create(tokens)
  return calc_parse_expression(parser)
}

fn calc_repl() {
  println("=== FreeLang v4 Calculator ===")
  println("Supports: +, -, *, /, %, ^ (power), ()")
  println("Functions: sqrt, sin, cos, tan, log, exp, abs, ...")
  println("Variables: x = 42, then use x")
  println("Constants: pi, e, tau")
  println("Type 'exit' to quit")
  println("")

  variables = {}

  while true {
    input = console_input("calc> ")
    if input == "exit" or input == "quit" { break }
    if input == "" { continue }

    tokens = calc_tokenize(input)
    parser = calc_parser_create(tokens)
    parser["variables"] = variables

    result = calc_parse_expression(parser)
    variables = parser["variables"]

    println("  = " + to_string(result))
  }

  println("Goodbye!")
}

